window.EXAM_PAPERS=window.EXAM_PAPERS||{};window.EXAM_PAPERS["1756566992"]={"id":"1756566992","title":"【判断推理】类比推理刷题题库","group":"专项练习","items":[{"id":"1718789647531","type":"single","material":"","stem":"净水器对于（）相当于（）对于汽缸","options":[{"label":"A","content":"滤芯;蒸汽机"},{"label":"B","content":"设备;元件"},{"label":"C","content":"家庭;发动机"},{"label":"D","content":"自来水;活塞"}],"answer":"A","explanation":"A项，滤芯是净水器的核心部件，汽缸是蒸汽机的核心部件，两组词项前后关系一致。<br>B项，净水器属于机器设备，汽缸属于机器元件，但元件和汽缸位置颠倒，两组词项前后关系不一致。<br>C项，净水器应用于家庭，汽缸是发动机的组成部分，两组词项前后关系不一致。<br>D项，净水器可以净化自来水，活塞是汽缸的组成部分，两组词项前后关系不一致。","no":1},{"id":"1718789647532","type":"single","material":"","stem":"日记对于（）相当于（）对于数据","options":[{"label":"A","content":"纪念;查证"},{"label":"B","content":"经历;内存"},{"label":"C","content":"年鉴;计算机"},{"label":"D","content":"日期;图片"}],"answer":"B","explanation":"A项，纪念是日记的功能，但数据不是查证的功能，两组词项前后关系不一致。<br>B项，日记可以记载经历，内存可以存储数据，两组词项前后关系一致。<br>C项，日记和年鉴都可以用来记事，计算机可以用来处理数据，两组词项前后关系不一致。<br>D项，日记按照日期来记录，图片不是按照数据来制作，两组词项前后关系不一致。","no":2},{"id":"1718789647533","type":"single","material":"","stem":"仪态万方：美丽多姿","options":[{"label":"A","content":"风度翩翩：富富有余"},{"label":"B","content":"腰缠万贯：富甲一方"},{"label":"C","content":"其貌不扬：荣华富贵"},{"label":"D","content":"仪表堂堂：身无长物"}],"answer":"B","explanation":"仪态万方和美丽多姿都形容容貌体态各方面都很美，两者含义相近。<br>A项，风度翩翩形容举止洒脱、气度不凡，富富有余多指财富，两者含义不同，排除。B项，腰缠万贯和富甲一方都是形容非常富有，两者含义相近。<br>C项，其貌不扬指相貌普通，荣华富贵形容有钱有势，两者含义不同，排除。<br>D项，仪表堂堂形容人外表端正、举止大方，身无长物形容贫穷，两者含义不同，排除。","no":3},{"id":"1718789647534","type":"single","material":"","stem":"扣子：西装：裤子","options":[{"label":"A","content":"鼠标：电脑：键盘"},{"label":"B","content":"学生：青年：艺术家"},{"label":"C","content":"窗帘：窗户：房子"},{"label":"D","content":"方向盘：轿车：商务车"}],"answer":"D","explanation":"西装和裤子都属于衣服，扣子是衣服的一部分。<br>A项，鼠标和键盘都是电脑的组成部分，与题干关系不一致。<br>B项，学生、青年、艺术家三者为交叉关系，与题干关系不一致。<br>C项，窗帘挂在窗户上，窗户是房子的一部分，与题干关系不一致。<br>D项，轿车和商务车都属于汽车，方向盘是汽车的一部分。与题干关系一致。","no":4},{"id":"1718789647535","type":"single","material":"","stem":"常规问题：非常规问题：问题","options":[{"label":"A","content":"期中考试：期末考试：考试"},{"label":"B","content":"顶层设计：基层落实：管理"},{"label":"C","content":"豪华装修：简单装修：装修"},{"label":"D","content":"转基因油：非转基因油：油"}],"answer":"D","explanation":"问题包括常规问题和非常规问题，两者是矛盾关系。<br>A项，期中考试和期末考试是反对关系，考试除了这两者之外，还有月考、资格证考试等，与题干关系不一致。<br>B项，顶层设计和基层落实是反对关系，与题干关系不一致。<br>C项，豪华装修和简单装修是反对关系，与题干关系不一致。<br>D项，油包括转基因油和非转基因油，两者是矛盾关系，与题干关系一致。","no":5},{"id":"1718789647536","type":"single","material":"","stem":"左顾右盼：上下打量","options":[{"label":"A","content":"南来北往：东西奔走"},{"label":"B","content":"纵横交错：中西合璧"},{"label":"C","content":"千叮万嘱：一心一意"},{"label":"D","content":"厚地高天：山清水秀"}],"answer":"A","explanation":"左、右、上、下均为不同的方位，左和右、上和下是反义关系，顾和盼是近义关系。<br>A项，南、北、东、西均为不同的方位，南和北、东和西是反义关系，来和往是近义关系。与题干关系一致。<br>B项，纵和横是反义关系，但题干是第一个词项中的第一个字和第三个字为反义关系。与题干关系不一致。<br>C项，千和万不是反义关系。与题干关系不一致。<br>D项，厚和高不是反义关系，地和天也不是近义关系。与题干关系不一致。","no":6},{"id":"1718789647537","type":"single","material":"","stem":"碗：水杯","options":[{"label":"A","content":"玻璃：书包"},{"label":"B","content":"光：蜡烛"},{"label":"C","content":"沙发：床"},{"label":"D","content":"电脑：娱乐"}],"answer":"C","explanation":"碗和水杯都是容器，两者为并列关系。<br>A项，玻璃和书包不是并列关系，与题干关系不一致。<br>B项，蜡烛会发出光，两者不是并列关系，与题干关系不一致。<br>C项，沙发和床都是家具，两者为并列关系，与题干关系一致。<br>D项，电脑可以用来娱乐，两者不是并列关系，与题干关系不一致。","no":7},{"id":"1718789647538","type":"single","material":"","stem":"桂林：北海","options":[{"label":"A","content":"墨汁：颜料"},{"label":"B","content":"开水：自来水"},{"label":"C","content":"氧气：空气"},{"label":"D","content":"红茶：黑茶"}],"answer":"D","explanation":"桂林和北海是并列关系，两者均是广西的城市。<br>A项，墨汁主要用于创作书法作品，但是也能作为一种绘画颜料使用，两者并不是完全并列的关系，与题干关系不一致。<br>B项，开水可以由自来水烧开得到，与题干关系不一致。<br>C项，氧气是空气的组成部分，与题干关系不一致。<br>D项，红茶和黑茶是并列关系，两者均是茶叶的一种，与题干关系一致。","no":8},{"id":"1718789647539","type":"single","material":"","stem":"<p>土地：耕种</p>","options":[{"label":"A","content":"共享单车：租金"},{"label":"B","content":"电子报纸：便利"},{"label":"C","content":"矩阵二维码：支付"},{"label":"D","content":"剪纸艺术：传播"}],"answer":"C","explanation":"<span>要解决这道类比推理题，需先分析题干逻辑：土地的功能是耕种，属于功能对应关系。</span><p><span>选项 A：共享单车的功能不是 “租金”，租金是使用它的代价，逻辑不符；</span><p><span>选项 B：“便利” 是电子报纸的属性，而非功能，逻辑不符；</span><p><span>选项 C：矩阵二维码的功能是 “支付”，属于功能对应，与题干逻辑一致；</span><p><span>选项 D：剪纸艺术的功能不是 “传播”，传播是其衍生行为，逻辑不符。</span><p>","no":9},{"id":"1718789647540","type":"single","material":"","stem":"灯：照明：装饰","options":[{"label":"A","content":"房子：明亮：宽敞"},{"label":"B","content":"水：浇灌：饮用"},{"label":"C","content":"中国：湖南：山西"},{"label":"D","content":"门窗：玻璃：钢铁"}],"answer":"B","explanation":"灯可以用来照明和装饰。<br>A项，明亮和宽敞是房子的特点，而非功能，与题干关系不一致。<br>B项，水可以用来浇灌和饮用，与题干关系一致。<br>C项，湖南和山西都是中国的城市，与题干关系不一致。<br>D项，玻璃和钢铁是制作门窗的原材料，与题干关系不一致。","no":10},{"id":"1718789647541","type":"single","material":"","stem":"收集素材：编辑整理：出版发行","options":[{"label":"A","content":"需求调研：软件开发：交付使用"},{"label":"B","content":"突发险情：山体滑坡：紧急救援"},{"label":"C","content":"购买车票：行李安检：预付票款"},{"label":"D","content":"网络搜索：实地考察：商家发货"}],"answer":"A","explanation":"先收集素材，然后编辑整理，最后出版发行，三者为顺承关系。<br>A项，先进行需求调研，然后进行软件开发，最后交付使用，三者为顺承关系。与题干关系一致。<br>B项，山体滑坡是突发险情的一种，两者为种属关系，突发险情需要紧急救援。与题干关系不一致，排除。<br>C项，网上购买车票需要预付票款，到车站后再进行行李安检。三个词项的顺序颠倒，与题干关系不一致，排除。<br>D项，网络搜索和实地考察不存在明确的顺承关系，且商家发货与前两个词项没有必然联系。与题干关系不一致，排除。","no":11},{"id":"1718789647542","type":"single","material":"","stem":"交通摄像头：监控路况","options":[{"label":"A","content":"指纹密码锁：采集指纹"},{"label":"B","content":"电子血压仪：测量血压"},{"label":"C","content":"扫地机器人：净化空气"},{"label":"D","content":"折叠防盗窗：晾晒衣服"}],"answer":"B","explanation":"题干中两个词语之间具有功能关系，前者为对象，后者是对其功能的描述。<br>交通摄像头的主要功能是监控路况。<br>A项，指纹密码锁的主要功能是利用指纹开锁，采集指纹只是实现功能的前提准备。B项，电子血压仪的主要功能是测量血压。<br>C项，扫地机器人的主要功能是扫地，而不是净化空气。<br>D项，折叠防盗窗的主要功能是防盗，而不是晾晒衣服。","no":12},{"id":"1718789647543","type":"single","material":"","stem":"三角形：三棱锥","options":[{"label":"A","content":"四边形：四面体"},{"label":"B","content":"五边形：五角星"},{"label":"C","content":"正方形：正方体"},{"label":"D","content":"抛物线：圆柱体"}],"answer":"C","explanation":"前项为平面图形，后项为立体图形，且后项的每一个面的图形都是前一项。<br>三棱锥的每一个面都是三角形。<br>A项，四面体是有四个面的立体图形，四个面都是三角形，而不是四边形。<br>B项，五角星不一定是立体图形。<br>C项，正方体的每一个面都是正方形。<br>D项，圆柱体有两个圆面和一个曲面，与抛物线无关。","no":13},{"id":"1718789647544","type":"single","material":"","stem":"茶水：咖啡：饮品","options":[{"label":"A","content":"误解：曲解：理解"},{"label":"B","content":"谎言：谗言：言论"},{"label":"C","content":"考试：考核：考验"},{"label":"D","content":"晋商：徽商：商人"}],"answer":"D","explanation":"茶水和咖啡是并列关系，二者都属于饮品。<br>A项，误解和曲解都是产生了不正确的理解，二者为近义关系，和理解为反义关系。B项，谎言是不真实的话，谗言是诽谤或者挑拨离间的话，二者为交叉关系。<br>C项，考试和考核都是一种测评形式，具有“考验”的目的，与题干关系不一致。<br>D项，晋商和徽商是并列关系，二者都属于商人，与题干关系一致。","no":14},{"id":"1718789647545","type":"single","material":"","stem":"有理数：无理数：实数","options":[{"label":"A","content":"洋房：楼房：房屋"},{"label":"B","content":"阴刻：阳刻：雕刻"},{"label":"C","content":"西汉：东汉：汉朝"},{"label":"D","content":"西欧：东欧：欧洲"}],"answer":"B","explanation":"实数分为有理数和无理数，二者和实数为种属关系。A项，洋房和楼房是交叉关系，与<br>题干关系不一致。<br>B项，雕刻分为阴刻和阳刻，二者和雕刻为种属关系，与题干关系一致。<br>C项，西汉和东汉是汉朝的组成部分，二者和汉朝是组成关系，与题干关系不一致。<br>D项，欧洲分为西欧、东欧、中欧、南欧和北欧。西欧和东欧都是欧洲的组成部分，二者和欧洲是组成关系，与题干关系不一致。","no":15},{"id":"1718789647546","type":"single","material":"","stem":"（）之于朋友相当于（）之于婚姻","options":[{"label":"A","content":"奋斗;金钱"},{"label":"B","content":"战友;同学"},{"label":"C","content":"真诚;爱情"},{"label":"D","content":"友善;勤奋"}],"answer":"C","explanation":"A项，奋斗和朋友，金钱和婚姻，均没有明显关系，不符。B项，战友和朋友是交叉关系，但同学和婚姻没有明显关系，不符。<br>C项，真诚是朋友的基础，爱情是婚姻的基础，前后逻辑关系一致，符合。<br>D项，朋友之间关系比较友善，但勤奋和婚姻没有明显关系，不符。","no":16},{"id":"1718789647547","type":"single","material":"","stem":"（）对于纸张相当于衣服对于（）","options":[{"label":"A","content":"书籍;布料"},{"label":"B","content":"树木;裤子"},{"label":"C","content":"宣纸;保暖"},{"label":"D","content":"笔墨;服装"}],"answer":"A","explanation":"A项，书籍可由纸张加工而成，衣服可由布料加工而成，均为成品和原材料的关系。前后关系一致。<br>B项，树木可加工成纸张，裤子是衣服的一种。前后关系不一致。<br>C项，宣纸属于纸张的一种，衣服具有保暖的作用。前后关系不一致。<br>D项，笔墨和纸张是并列关系，衣服属于服装。前后关系不一致。","no":17},{"id":"1718789647548","type":"single","material":"","stem":"《本草纲目》:李时珍：明朝","options":[{"label":"A","content":"《齐民要术》:贾思勰：三国"},{"label":"B","content":"《海国图志》:林则徐：清朝"},{"label":"C","content":"《梦溪笔谈》:沈括：南宋"},{"label":"D","content":"《茶经》:陆羽：唐朝"}],"answer":"D","explanation":"《本草纲目》是明朝李时珍的著作。<br>A项，《齐民要术》是北魏末年贾思勰的著作，年代不符，和题干关系不一致。<br>B项，《海国图志》是清朝魏源的著作，作者不符，和题干关系不一致。<br>C项，《梦溪笔谈》是北宋沈括的著作，年代不符，和题干关系不一致。<br>D项，《茶经》是唐朝陆羽的著作，和题干关系一致。","no":18},{"id":"1718789647549","type":"single","material":"","stem":"姚明：中国：篮球","options":[{"label":"A","content":"梅西：巴西：足球"},{"label":"B","content":"伍兹：美国：棒球"},{"label":"C","content":"费德勒：西班牙：网球"},{"label":"D","content":"瓦尔德内尔：瑞典：乒乓球"}],"answer":"D","explanation":"姚明是中国的篮球运动员。<br>A项，梅西是阿根廷的足球运动员，国籍不符，和题干关系不一致。<br>B项，伍兹是美国的高尔夫球运动员，运动项目不符，和题干关系不一致。<br>C项，费德勒是瑞士的网球运动员，国籍不符，和题干关系不一致。<br>D项，瓦尔德内尔是瑞典的乒乓球运动员，和题干关系一致。","no":19},{"id":"1718789647550","type":"single","material":"","stem":"钢笔：圆珠笔：铅笔","options":[{"label":"A","content":"肥皂：皂角：香皂"},{"label":"B","content":"杆秤：磅秤：台秤"},{"label":"C","content":"桌子：凳子：椅子"},{"label":"D","content":"燃气灶：电视机：洗衣机"}],"answer":"B","explanation":"钢笔、圆珠笔、铅笔都属于笔，功能相似。<br>A项，肥皂和香皂为并列关系，功能相似，但皂角是制作肥皂和香皂的原材料，和题干关系不一致。<br>B项，杆秤、磅秤、台秤都属于秤，功能相似，和题干关系一致。<br>C项，桌子、凳子、椅子都属于家具，但凳子和椅子功能相似，桌子和这二者功能不同，和题干关系不一致。<br>D项，燃气灶、电视机、洗衣机都属于家用电器，但功能各不相同，和题干关系不一致。","no":20},{"id":"1718789647551","type":"single","material":"","stem":"旗开得胜：马到成功","options":[{"label":"A","content":"拨乱反正：沉冤昭雪"},{"label":"B","content":"牛高马大：虎穴得子"},{"label":"C","content":"水到渠成：瓜熟蒂落"},{"label":"D","content":"缘木求鱼：鹰击长空"}],"answer":"C","explanation":"旗开得胜和马到成功都比喻事情刚开始就取得成功，两者是近义关系。<br>A项，拨乱反正是指消除混乱局面，恢复正常秩序。沉冤昭雪是指沉积很久的冤情得到洗刷。两者不是近义关系，排除。<br>B项，牛高马大比喻人长得高大强壮。虎穴得子比喻诗文贴切中肯且深得其要旨。两者不是近义关系，排除。<br>C项，水到渠成和瓜熟蒂落都比喻条件成熟后事情自然会成功。两者为近义关系，与题干关系一致。<br>D项，缘木求鱼比喻方法不对，不可能达到目的。鹰击长空是指有雄心壮志的人在广阔的领域中施展自己的才能。两者不是近义关系，排除。","no":21},{"id":"1718789647552","type":"single","material":"","stem":"大漠对于（）相当于草原对于（）","options":[{"label":"A","content":"黄沙;蒙古包"},{"label":"B","content":"干旱;牧场"},{"label":"C","content":"骆驼;羊"},{"label":"D","content":"绿洲;雪山"}],"answer":"C","explanation":"A项，黄沙是大漠的组成部分，蒙古包建在草原上，前后逻辑关系不一致，排除。<br>B项，干旱是大漠的特点，牧场建在草原上，前后逻辑关系不一致，排除。<br>C项，骆驼是大漠中的动物，羊是草原上的动物，前后逻辑关系一致。<br>D项，大漠里可能会有绿洲，但草原里并没有雪山，草原和雪山是并列关系，两者是不同的自然景观，前后逻辑关系不一致。","no":22},{"id":"1718789647553","type":"single","material":"","stem":"花容月貌对于（）相当于（）对于言语","options":[{"label":"A","content":"漂亮;巧舌如簧"},{"label":"B","content":"美丽;甜言蜜语"},{"label":"C","content":"姿色;言外之意"},{"label":"D","content":"容貌;花言巧语"}],"answer":"D","explanation":"A项，花容月貌形容女子容貌美丽，和漂亮是近义关系；巧舌如簧形容能说会道，善于狡辩，和言语不是近义关系。前后关系不一致。<br>B项，花容月貌形容女子容貌美丽，和美丽是近义关系；甜言蜜语形容为了讨人喜欢或哄骗人而说的好听的话，和言语不是近义关系。前后关系不一致。<br>C项，花容月貌形容女子容貌美丽，是对姿色的形容；言外之意指话里暗含着的没有直接说出的意思，和言语没有明显关系。前后关系不一致。<br>D项，花容月貌形容女子容貌美丽，是对容貌的比喻；花言巧语形容虚假而动听的话，是对言语的比喻。前后关系一致。","no":23},{"id":"1718789647554","type":"single","material":"","stem":"语言：德语","options":[{"label":"A","content":"图书馆：书本"},{"label":"B","content":"命题：概念"},{"label":"C","content":"有理数：正分数"},{"label":"D","content":"地球：卫星"}],"answer":"C","explanation":"语言包含德语，二者是种属关系。<br>A项，书本放在图书馆中，与题干关系不一致。<br>B项，命题是一种概念，与题干关系不一致。<br>C项，有理数包含正分数，与题干关系一致。<br>D项，地球和卫星不存在明显的关系，与题干关系不一致。","no":24},{"id":"1718789647555","type":"single","material":"","stem":"亭台：楼宇：砖瓦","options":[{"label":"A","content":"彩虹：阳光：屋景"},{"label":"B","content":"电闪：雷鸣：电荷"},{"label":"C","content":"蛋糕：面包：面粉"},{"label":"D","content":"核聚变：核裂变：核能"}],"answer":"C","explanation":"亭台和楼宇为并列关系，其建造需要砖瓦。<br>A项，彩虹和阳光为并列关系，屋景不是其原材料，与题干关系不一致。<br>B项，电荷不是电闪雷鸣的原材料，与题干关系不一致。<br>C项，蛋糕、面包的制作需要面粉，且二者为并列关系，与题干关系一致。<br>D项，核聚变和核裂变都可以释放核能，与题干关系不一致。","no":25},{"id":"1718789647556","type":"single","material":"","stem":"漫画：推理漫画：连环漫画","options":[{"label":"A","content":"可见光：红光：紫光"},{"label":"B","content":"文物：馆藏文物：史前文物"},{"label":"C","content":"大气：对流层：中间层"},{"label":"D","content":"离子：阳离子：阴离子"}],"answer":"B","explanation":"漫画包含推理漫画和连环漫画，推理漫画和连环漫画是交叉关系。<br>A项，可见光包含红光和紫光，红光和紫光是并列关系，与题干关系不一致。<br>B项，文物包含馆藏文物和史前文物，馆藏文物和史前文物是交叉关系，与题干关系一致。<br>C项，大气包含对流层和中间层，中间层和对流层是并列关系，与题干关系不一致。<br>D项，离子包含阳离子和阴离子，阳离子和阴离子是并列关系，与题干关系不一致。","no":26},{"id":"1718789647557","type":"single","material":"","stem":"经理：法官：公务员","options":[{"label":"A","content":"总统：明星：演员"},{"label":"B","content":"蛋白质：花岗岩：无机物"},{"label":"C","content":"农具：沙发：家具"},{"label":"D","content":"原告：被告：当事人"}],"answer":"C","explanation":"经理和公务员为并列关系，法官属于公务员。<br>A项，总统和明星为交叉关系，明星和演员为交叉关系，与题干关系不一致。<br>B项，蛋白质属于有机物，有机物和无机物为并列关系，无机物是花岗岩的组成部分，与题干关系不一致。<br>C项，农具和沙发为并列关系，沙发属于家具，与题干关系一致。<br>D项，原告和被告为并列关系，原告和被告都属于当事人，与题干关系不一致。","no":27},{"id":"1718789647558","type":"single","material":"","stem":"（）对于社会科学相当于蝗虫对于（）","options":[{"label":"A","content":"自然科学;害虫"},{"label":"B","content":"超声波;大雁"},{"label":"C","content":"物理学;蜻蜓"},{"label":"D","content":"经济学;昆虫"}],"answer":"D","explanation":"A项，自然科学和社会科学为并列关系，蝗虫属于害虫，是种属关系，前后关系不一致。<br>B项，超声波和社会科学不具有明显关系，蝗虫和大雁是并列关系，前后关系不<br>一致。<br>C项，物理学和社会科学不具有明显关系，蝗虫和蜻蜓是并列关系，前后关系不一致。<br>D项，经济学属于社会科学，蝗虫属于昆虫，前后关系一致。","no":28},{"id":"1718789647559","type":"single","material":"","stem":"混合物：空气","options":[{"label":"A","content":"财务报表：利润表"},{"label":"B","content":"金属：绝缘体"},{"label":"C","content":"合唱团：团员"},{"label":"D","content":"满族：维吾尔族"}],"answer":"A","explanation":"空气是一种混合物。<br>A项，利润表是一种财务报表，与题干关系一致。<br>B项，绝缘体不属于金属，与题干关系不一致。<br>C项，团员属于合唱团的组成部分，与题干关系不一致。<br>D项，满族和维吾尔族是并列关系，与题干关系不一致。","no":29},{"id":"1718789647560","type":"single","material":"","stem":"紫外线对于（）相当于单晶体对于（）","options":[{"label":"A","content":"臭氧层;晶体"},{"label":"B","content":"电磁波;石英"},{"label":"C","content":"可见光;非晶体"},{"label":"D","content":"红外线;石墨"}],"answer":"C","explanation":"A项，臭氧层能吸收紫外线，单晶体属于晶体，前后关系不一致。B项，紫外线和电磁波是并列关系，石英属于单晶体，前后关系不一致。<br>C项，紫外线是不可见光的一种，不可见光与可见光是矛盾关系；单晶体是晶体的一种，晶体与非晶体是矛盾关系，前后关系一致。<br>D项，紫外线和红外线是并列关系，石墨属于单晶体，前后关系不一致。","no":30},{"id":"1718789647561","type":"single","material":"","stem":"摄影：绘画","options":[{"label":"A","content":"复印：扫描"},{"label":"B","content":"书法：刺绣"},{"label":"C","content":"雕刻：打磨"},{"label":"D","content":"歌唱：弹奏"}],"answer":"D","explanation":"摄影和绘画是对图像不同的呈现方式。<br>A项，扫描是复印的一个环节，与题干关系不一致。<br>B项，书法和刺绣都是技艺，并非对同一事物的不同呈现方式，与题干关系不一致。C项，雕刻需要打磨，与题干关系不一致。<br>D项，歌唱和弹奏是对乐曲不同的呈现方式，与题干关系一致。","no":31},{"id":"1718789647562","type":"single","material":"","stem":"头发：理发剪","options":[{"label":"A","content":"指甲：指甲钳"},{"label":"B","content":"橡皮：橡皮擦"},{"label":"C","content":"铅笔：铅笔盒"},{"label":"D","content":"蜜糖：蜜糖罐"}],"answer":"A","explanation":"理发剪有剪头发的作用。<br>A项，指甲钳有剪指甲的作用，与题干关系一致。<br>B项，橡皮擦又叫橡皮，两者是全同关系，与题干关系不一致。<br>C项，铅笔放在铅笔盒里，与题干关系不一致。<br>D项，蜜糖放在蜜糖罐里，与题干关系不一致。","no":32},{"id":"1718789647563","type":"single","material":"","stem":"稻谷：粮食：种植","options":[{"label":"A","content":"钢笔：文具：绘画"},{"label":"B","content":"水果：西瓜：切割"},{"label":"C","content":"人才：资源：培养"},{"label":"D","content":"煤炭：石油：挖掘"}],"answer":"C","explanation":"稻谷是一种粮食，种植稻谷。<br>A项，钢笔是一种文具，用钢笔来绘画，与题干关系不一致，排除。<br>B项，西瓜是一种水果，选项中水果和西瓜的位置颠倒，与题干关系不一致，排除。C项，人才是一种资源，培养人才，与题干关系一致。<br>D项，煤炭和石油都属于资源，两者为并列关系，与题干关系不一致，排除。","no":33},{"id":"1718789647564","type":"single","material":"","stem":"人民币：美元：兑换","options":[{"label":"A","content":"现金：支票：货币"},{"label":"B","content":"写作：绘画：文字"},{"label":"C","content":"诗词：音乐：旋律"},{"label":"D","content":"中文：英文：翻译"}],"answer":"D","explanation":"人民币和美元是并列关系，两者均为货币，可以相互兑换。<br>A项，现金和支票是并列关系，两者均为货币。与题干关系不一致，排除。<br>B项，写作和绘画是并列关系，写作需要运用文字。与题干关系不一致，排除。<br>C项，诗词可以用音乐的形式传达，音乐有旋律。与题干关系不一致，排除。<br>D项，中文和英文是并列关系，两者均为语言，可以相互翻译。与题干关系一致。","no":34},{"id":"1718789647565","type":"single","material":"","stem":"红酒：咖啡：饮品","options":[{"label":"A","content":"熊猫：刺绣：中国"},{"label":"B","content":"勺子：铲子：金属"},{"label":"C","content":"邮票：信封：邮寄"},{"label":"D","content":"板栗：核桃：干果"}],"answer":"D","explanation":"红酒和咖啡为并列关系，二者都属于饮品，为种属关系。<br>A项，熊猫是一种动物，刺绣是一种艺术形式，均原产于中国，与题干关系不一致。B项，勺子和铲子为并列关系，金属可能是二者的原料，与题干关系不一致。<br>C项，邮寄信件需要邮票和信封，邮票和信封为配套关系，与题干关系不一致。<br>D项，板栗和核桃为并列关系，且二者与干果构成种属关系，与题干关系一致。","no":35},{"id":"1718789647566","type":"single","material":"","stem":"白醋：消毒","options":[{"label":"A","content":"热水器：加热"},{"label":"B","content":"汽油：去渍"},{"label":"C","content":"白糖：调味"},{"label":"D","content":"人参：滋补"}],"answer":"B","explanation":"白醋可以消毒，但消毒不是白醋的主要功能。<br>A项，热水器的主要功能就是加热，与题干关系不一致。<br>B项，汽油可以去渍，但去渍不是汽油的主要功能，与题干关系一致。<br>C项，白糖的主要功能就是调味，与题干关系不一致。<br>D项，人参的主要功能就是滋补，与题干关系不一致。","no":36},{"id":"1718789647567","type":"single","material":"","stem":"生死：存亡","options":[{"label":"A","content":"轻重：缓急"},{"label":"B","content":"亲疏：长幼"},{"label":"C","content":"真伪：对错"},{"label":"D","content":"好坏：优劣"}],"answer":"D","explanation":"生和死、存和亡均为反义词，生和存、死和亡均为同义词。<br>A项，轻和重、缓和急均为反义词，但轻和缓、重和急并非同义词，与题干关系不一致。<br>B项，亲和疏、长和幼均为反义词，但亲和长、疏和幼并非同义词，与题干关系不一致。<br>C项，真和伪、对和错均为反义词，但真和对、伪和错并非同义词，与题干关系不一致。<br>D项，好和坏、优和劣均为反义词，好和优、坏和劣均为同义词，与题干关系一致。","no":37},{"id":"1718789647568","type":"single","material":"","stem":"设计：发放：问卷","options":[{"label":"A","content":"播放：快进：磁带"},{"label":"B","content":"制定：执行：政策"},{"label":"C","content":"复制：修改：文字"},{"label":"D","content":"预习：复习：考试"}],"answer":"B","explanation":"先设计问卷，然后发放问卷。<br>A项，播放磁带和快进磁带之间并没有顺承关系，与题干关系不一致。<br>B项，先制定政策，然后执行政策，与题干关系一致。<br>C项，复制文字和修改文字之间并没有顺承关系，与题干关系不一致。<br>D项，预习考试搭配不当，不能构成动宾结构的短语，与题干关系不一致。","no":38},{"id":"1718789647569","type":"single","material":"","stem":"火：火热","options":[{"label":"A","content":"金：金黄"},{"label":"B","content":"水：水润"},{"label":"C","content":"土：土气"},{"label":"D","content":"木：木讷"}],"answer":"B","explanation":"火热的热是火的内在特征。<br>A项，金黄的黄是金的外在特征，与题干关系不一致。<br>B项，水润的润是水的内在特征，与题干关系一致。<br>C项，土气的气不是土的内在特征，与题干关系不一致。<br>D项，木讷的讷不是木的内在特征，与题干关系不一致。","no":39},{"id":"1718789647570","type":"single","material":"","stem":"<p>猪：猪肝</p>","options":[{"label":"A","content":"鱼：鱼鳔"},{"label":"B","content":"马：马蹄"},{"label":"C","content":"虫：虫草"},{"label":"D","content":"虾：虾须"}],"answer":"A","explanation":"猪肝是猪的一个内脏器官。A项，鱼鳔是鱼的一个内脏器官，与题干关系一致。B项，马蹄不是马的内脏器官，与题干关系不一致。C项，虫草不是虫的内脏器官，与题干关系不一致。D项，虾须不是虾的内脏器官，与题干关系不一致。","no":40},{"id":"1718789647571","type":"single","material":"","stem":"处之泰然：镇定","options":[{"label":"A","content":"大义凛然：壮烈"},{"label":"B","content":"虚怀若谷：谦虚"},{"label":"C","content":"杳如黄鹤：消失"},{"label":"D","content":"似水流年：时间"}],"answer":"B","explanation":"处之泰然指沉着冷静，可以形容镇定，且二者是近义关系。<br>A项，大义凛然指由于胸怀正义而神态庄严，令人敬畏，不可以形容壮烈，与题干关系不一致。<br>B项，虚怀若谷形容非常虚心，可以形容谦虚，且二者是近义关系，与题干关系一致。C项，杳如黄鹤比喻下落不明，不可以形容消失，与题干关系不一致。<br>D项，似水流年指时间一去不复返，可以形容时间，但不是近义关系，与题干关系不一致。","no":41},{"id":"1718789647572","type":"single","material":"","stem":"<p>（ &nbsp; ）对于针灸相当于理财对于（ &nbsp; ）</p>","options":[{"label":"A","content":"中药；消费"},{"label":"B","content":"中医；银行"},{"label":"C","content":"治疗；储蓄"},{"label":"D","content":"推拿；利息"}],"answer":"C","explanation":"A项，中药和针灸都是中医的范畴，理财和消费是钱的不同用处，前后关系不一致。B项，针灸是中医的范畴，理财是银行的功能，前后关系不一致。C项，针灸是治疗的一种方式，储蓄是理财的一种方式，前后关系一致。D项，推拿和针灸都是中医的范畴，理财可以获取利息，前后关系不一致。","no":42},{"id":"1718789647573","type":"single","material":"","stem":"犹疑：深信","options":[{"label":"A","content":"晚造：提前"},{"label":"B","content":"老到：幼稚"},{"label":"C","content":"婉拒：褒扬"},{"label":"D","content":"爽利：强横"}],"answer":"B","explanation":"犹疑的反义词是深信，二者是反义关系。<br>A项，晚造指晚季作物，和提前不是反义关系，与题干关系不一致。<br>B项，老到的反义词是幼稚，二者是反义关系，与题干关系一致。<br>C项，婉拒和褒扬不是反义关系，与题干关系不一致。<br>D项，爽利和强横不是反义关系，与题干关系不一致。","no":43},{"id":"1718789647574","type":"single","material":"","stem":"进士：状元","options":[{"label":"A","content":"河水：海水"},{"label":"B","content":"银河：天文"},{"label":"C","content":"学位：博士"},{"label":"D","content":"宪法：民法"}],"answer":"C","explanation":"进士中最好的名次是状元。<br>A项，河水和海水是并列关系，与题干关系不一致。<br>B项，银河是天文学的研究对象，与题干关系不一致。<br>C项，学位中最高的是博士，与题干关系一致。<br>D项，宪法是国家的根本法，民法是民法体系中的一般法，民法的制定要以宪法为依据，二者不是种属关系，与题干关系不一致。","no":44},{"id":"1718789647575","type":"single","material":"","stem":"救援：围魏救赵","options":[{"label":"A","content":"进攻：风声鹤唳"},{"label":"B","content":"防守：草木皆兵"},{"label":"C","content":"追击：穷寇勿追"},{"label":"D","content":"转移：斗折蛇行"}],"answer":"C","explanation":"围魏救赵是进行救援时的一种兵家计策。<br>A项，风声鹤唳是指听到风声和鹤叫声，都疑心是追兵，形容惊慌失措，或自相惊扰的样子，和进攻无关，与题干关系不一致。<br>B项，草木皆兵是指把山上的草木都当作敌兵，形容人在惊慌时疑神疑鬼，和防守无关，与题干关系不一致。<br>C项，穷寇勿追是追击时的一种兵法思想，与题干关系一致。<br>D项，斗折蛇行形容道路曲折，和转移无关，与题干关系不一致。","no":45},{"id":"1718789647576","type":"single","material":"","stem":"词典：词语","options":[{"label":"A","content":"地图：地点"},{"label":"B","content":"盲文：阅读"},{"label":"C","content":"电影：台词"},{"label":"D","content":"电脑：游戏"}],"answer":"A","explanation":"在词典中查询词语，查询词语是词典的主要功能。A项，在地图上查询地点，与题干关系一致。<br>B项，盲文可以用来阅读，但不能查询，与题干关系不一致。<br>C项，电影包含台词，与题干关系不一致。<br>D项，电脑可以用来玩游戏，但玩游戏不是电脑的主要功能，与题干关系不一致。","no":46},{"id":"1718789647577","type":"single","material":"","stem":"<p>扶贫之于（ &nbsp; ）相当于深化改革之于（ &nbsp; ）</p>","options":[{"label":"A","content":"小康社会；国家治理现代化"},{"label":"B","content":"和谐社会；科学发展观"},{"label":"C","content":"社会动员；大国治理"},{"label":"D","content":"从严治党；依法治国"}],"answer":"A","explanation":"代入A项，扶贫的目的是实现小康社会，深化改革的目的是推进国家治理现代化。前后关系一致。代入B项，扶贫有助于构建和谐社会，科学发展观是深化改革的理论前提。前后关系不一致，排除。代入C项，扶贫需要社会动员，大国治理需要深化改革。但词项的前后顺序颠倒，排除。代入D项，扶贫与从严治党并无必然联系，深化改革和依法治国是“四个全面”的组成部分。前后关系不一致，排除。","no":47},{"id":"1718789647578","type":"single","material":"","stem":"生产：销售","options":[{"label":"A","content":"收入：支出"},{"label":"B","content":"起草：修改"},{"label":"C","content":"救灾：抗灾"},{"label":"D","content":"闭幕：开幕"}],"answer":"B","explanation":"先生产然后才能销售。<br>A项，支出未必要先有收入，与题干关系不一致，排除。<br>B项，先起草然后才能修改，与题干关系一致。<br>C项，救灾和抗灾并无明显的先后顺序，很多时候是同时进行的，与题干关系不一致，排除。<br>D项，应先开幕，再闭幕，与题干关系一致，但词项间顺序颠倒，排除。","no":48},{"id":"1718789647579","type":"single","material":"","stem":"丝绸之路之于（）相当于万里长征之于（）","options":[{"label":"A","content":"敦煌;遵义"},{"label":"B","content":"骆驼;草鞋"},{"label":"C","content":"沙漠;海洋"},{"label":"D","content":"贸易;解放"}],"answer":"A","explanation":"代入A项，敦煌是丝绸之路上的一站，遵义是万里长征中的一站。前后关系一致<br>。<br>代入B项，骆驼是丝绸之路上必不可少的，草鞋并非万里长征中必不可少的，并非每一个红军战士穿的都是草鞋。前后关系不一致。<br>代入C项，丝绸之路会经过沙漠，但万里长征并没有经过海洋。前后关系不一致。<br>代入D项，丝绸之路是为了进行贸易，万里长征是为了进行战略转移，而非解放。前后关系不一致。","no":49},{"id":"1718789647580","type":"single","material":"","stem":"聪明：耳聪目明","options":[{"label":"A","content":"长安：长治久安"},{"label":"B","content":"卑鄙：卑微鄙陋"},{"label":"C","content":"悲愤：悲痛愤怒"},{"label":"D","content":"辨症：辨别症候"}],"answer":"B","explanation":"聪明古今含义不同，在古代是耳聪目明的意思。<br>A项，长安在古代指的是西安，并非长治久安，与题干关系不一致。<br>B项，卑鄙古今含义不同，在古代是卑微鄙陋的意思，与题干关系一致。<br>C项，悲愤古今含义相同，都是悲痛愤怒的意思，与题干关系不一致。<br>D项，辨症古今含义相同，都是辨别症候的意思，与题干关系不一致。","no":50},{"id":"1718789647581","type":"single","material":"","stem":"厨房：高压锅：电饭煲","options":[{"label":"A","content":"运动场：球迷：座位"},{"label":"B","content":"教室：课桌：讲台"},{"label":"C","content":"书桌：书架：台灯"},{"label":"D","content":"农田：水稻：水牛"}],"answer":"B","explanation":"厨房里有高压锅和电饭煲，高压锅和电饭煲是并列关系。<br>A项，运动场里有球迷和座位，球迷坐在座位上，后两个词项间并不是并列关系，与题干关系不一致。<br>B项，教室里有课桌和讲台，课桌和讲台是并列关系，与题干关系一致。<br>C项，书桌与书架是并列关系，台灯在书桌上，与题干关系不一致。<br>D项，农田里有水稻和水牛，但水稻是植物，水牛是动物，两者并不是并列关系，与题干关系不一致。","no":51},{"id":"1718789647582","type":"single","material":"","stem":"黑色：颜色","options":[{"label":"A","content":"米饭：粮食"},{"label":"B","content":"小草：树木"},{"label":"C","content":"粗心：信心"},{"label":"D","content":"鱼：湖泊"}],"answer":"A","explanation":"黑色是一种颜色，两者为种属关系。<br>A项，米饭是一种粮食，两者为种属关系，与题干关系一致。<br>B项，小草和树木都是植物，两者为并列关系，与题干关系不一致。<br>C项，粗心和信心并无必然联系，与题干关系不一致。<br>D项，鱼生活在湖泊中，两者并非种属关系，与题干关系不一致。","no":52},{"id":"1718789647583","type":"single","material":"","stem":"电动汽车：电动车：汽车","options":[{"label":"A","content":"航天飞机：宇宙飞船：飞行器"},{"label":"B","content":"军医：医生：军人"},{"label":"C","content":"研究生：研究：学生"},{"label":"D","content":"法官：法律：官员"}],"answer":"B","explanation":"电动汽车既是电动车又是汽车。<br>A项，航天飞机和宇宙飞船是并列关系，两者都属于飞行器，与题干关系不一致。B项，军医既是医生又是军人，与题干关系一致。<br>C项，研究生属于学生，但研究生和研究并非种属关系，与题干关系不一致。<br>D项，法官运用法律判决，两者之间并非种属关系，与题干关系不一致。","no":53},{"id":"1718789647584","type":"single","material":"","stem":"嬴政：吕不韦","options":[{"label":"A","content":"刘邦：张良"},{"label":"B","content":"赵匡胤：赵普"},{"label":"C","content":"朱翊钧：张居正"},{"label":"D","content":"刘禅：诸葛亮"}],"answer":"B","explanation":"嬴政是秦朝开国皇帝，吕不韦是辅佐嬴政的丞相。<br>A项，刘邦是汉朝开国皇帝，张良不是刘邦的丞相，与题干关系不一致。<br>B项，赵匡胤是宋朝开国皇帝，赵普是辅佐赵匡胤的丞相，与题干关系一致。<br>C项，朱翊钧不是明朝开国皇帝，与题干关系不一致。<br>D项，刘禅不是蜀汉开国皇帝，与题干关系不一致。","no":54},{"id":"1718789647585","type":"single","material":"","stem":"教师：陕西人","options":[{"label":"A","content":"彩虹：云雾"},{"label":"B","content":"青年：学生"},{"label":"C","content":"《永乐大典》:《四库全书》"},{"label":"D","content":"大熊猫：金丝猴"}],"answer":"B","explanation":"教师可以是陕西人，陕西人也可以是教师。<br>A项，彩虹和云雾是两种并列的自然现象，与题干关系不一致。<br>B项，青年可以是学生，学生也可以是青年，与题干关系一致。<br>C项，《永乐大典》和《四库全书》是两部并列的作品集，与题干关系不一致。<br>D项，大熊猫和金丝猴是两种并列的动物，与题干关系不一致。","no":55},{"id":"1718789647586","type":"single","material":"","stem":"头：脚","options":[{"label":"A","content":"白天：黑夜"},{"label":"B","content":"男人：女人"},{"label":"C","content":"好：孬"},{"label":"D","content":"红：蓝"}],"answer":"D","explanation":"头和脚是反对关系。<br>A项，白天和黑夜是矛盾关系，与题干关系不一致。<br>B项，男人和女人是矛盾关系，与题干关系不一致。<br>C项，好和孬是矛盾关系，与题干关系不一致。<br>D项，红和蓝是反对关系，与题干关系一致。","no":56},{"id":"1718789647587","type":"single","material":"","stem":"烟灰：烟灰缸","options":[{"label":"A","content":"黑板：黑板擦"},{"label":"B","content":"鼠标：鼠标垫"},{"label":"C","content":"首饰：首饰盒"},{"label":"D","content":"领带：领带夹"}],"answer":"C","explanation":"烟灰盛放在烟灰缸中。<br>A项，黑板擦用来擦黑板，与题干关系不一致。<br>B项，鼠标放置于鼠标垫上，与题干关系不一致。<br>C项，首饰收藏在首饰盒里，与题干关系一致。<br>D项，领带夹夹在领带上，与题干关系不一致。","no":57},{"id":"1718789647588","type":"single","material":"","stem":"进展：变化","options":[{"label":"A","content":"妥协：退让"},{"label":"B","content":"口角：冲突"},{"label":"C","content":"开花：结果"},{"label":"D","content":"喜欢：信任"}],"answer":"B","explanation":"进展是一种变化。<br>A项，妥协和退让为近义词，与题干关系不一致。<br>B项，口角是一种冲突，与题干关系一致。<br>C项，开花和结果与题干关系不一致。<br>D项，喜欢和信任与题干关系不一致。","no":58},{"id":"1718789647589","type":"single","material":"","stem":"玫瑰：植物：动物","options":[{"label":"A","content":"童话：书籍：影像"},{"label":"B","content":"画眉：鸟：鱼"},{"label":"C","content":"镜片：太阳镜：墨镜"},{"label":"D","content":"雾：雨：风"}],"answer":"B","explanation":"玫瑰属于植物，植物和动物是并列关系。<br>A项，童话可以用书籍记录，也可以用影像记录，与题干关系不一致。B项，画眉属于鸟，鸟和鱼是并列关系，和题干关系一致。<br>C项，太阳镜和墨镜属于同一物品的不同称谓，与题干关系不一致。<br>D项，雾、雨、风是并列关系，与题干关系不一致。","no":59},{"id":"1718789647590","type":"single","material":"","stem":"口试：笔试：招聘","options":[{"label":"A","content":"摄影：购物：旅游"},{"label":"B","content":"招标：中标：建设"},{"label":"C","content":"批发：零售：销售"},{"label":"D","content":"出口：内销：商品"}],"answer":"C","explanation":"口试和笔试是招聘采用的两种不同形式。A项，摄影、购物、旅游是并列关系，与题干关系不一致。<br>B项，招标、中标、建设是顺承关系，与题干关系不一致。<br>C项，批发和零售是销售时采用的两种不同方式，与题干关系一致。<br>D项，商品可以出口，也可以内销，与题干关系不一致。","no":60},{"id":"1718789647591","type":"single","material":"","stem":"面粉：面包：烤箱","options":[{"label":"A","content":"水彩：纸张：画笔"},{"label":"B","content":"麦粒：油条：磨子"},{"label":"C","content":"粮食：酒：酒壶"},{"label":"D","content":"棉花：布：织布机"}],"answer":"D","explanation":"面粉是制作面包的原料，烤箱是制作面包的工具。A项，水彩不是制作纸张的原料，与题干关系不一致。<br>B项，磨子不是制作油条的工具，与题干关系不一致。<br>C项，酒壶不是制作酒的工具，与题干关系不一致。<br>D项，棉花是制作布的原料，织布机是制作布的工具，和题干关系一致。","no":61},{"id":"1718789647592","type":"single","material":"","stem":"学者：物理学家：爱因斯坦","options":[{"label":"A","content":"世界：亚洲：印度"},{"label":"B","content":"诗歌：唐诗：格律诗"},{"label":"C","content":"河流：中国河流：长江"},{"label":"D","content":"中国：中国城市：南京"}],"answer":"C","explanation":"学者包含物理学家，物理学家包含爱因斯坦。A项，亚洲是世界的组成部分，与题干关系不一致。<br>B项，唐诗和格律诗是交叉关系，与题干关系不一致。<br>C项，河流包含中国河流，中国河流包含长江，与题干关系一致。<br>D项，中国城市是中国的组成部分，与题干关系不一致。","no":62},{"id":"1718789647593","type":"single","material":"","stem":"苏格拉底：人类","options":[{"label":"A","content":"松树：植物"},{"label":"B","content":"故宫：建筑"},{"label":"C","content":"《唐诗三百首》:书籍"},{"label":"D","content":"太阳：恒星"}],"answer":"D","explanation":"人类包含苏格拉底，苏格拉底特指古希腊哲学家。<br>A项，植物包含松树，但松树是一类树，与题干关系不一致。<br>B项，建筑包含故宫，但故宫是建筑群，与题干关系不一致。<br>C项，书籍包含《唐诗三百首》,但《唐诗三百首》是很多诗组成的诗集，与题干关系不一致。<br>D项，恒星包含太阳，太阳特指太阳系的太阳，与题干关系一致。","no":63},{"id":"1718789647594","type":"single","material":"","stem":"蛇：腿","options":[{"label":"A","content":"牛：尾巴"},{"label":"B","content":"鲸：鱼鳃"},{"label":"C","content":"鸡：翅膀"},{"label":"D","content":"狮：爪子"}],"answer":"B","explanation":"蛇没有腿。<br>A项，牛有尾巴，与题干关系不一致。<br>B项，鲸没有鱼鳃，与题干关系一致。<br>C项，鸡有翅膀，与题干关系不一致。<br>D项，狮有爪子，与题干关系不一致。","no":64},{"id":"1718789647595","type":"single","material":"","stem":"人文科学：物理","options":[{"label":"A","content":"工业：重工业"},{"label":"B","content":"薄荷糖：牛奶糖"},{"label":"C","content":"茶叶：红茶"},{"label":"D","content":"北方人：湖北人"}],"answer":"D","explanation":"物理不属于人文科学。<br>A项，重工业属于工业，与题干关系不一致。<br>B项，薄荷糖和牛奶糖可以是交叉关系，两者没有严格的界限区分，与题干关系不一致。<br>C项，红茶属于茶叶，与题干关系不一致。<br>D项，湖北人不属于北方人，与题干关系一致。","no":65},{"id":"1718789647596","type":"single","material":"","stem":"逻辑学：光学","options":[{"label":"A","content":"芝士：奶酪"},{"label":"B","content":"教师：医生"},{"label":"C","content":"黄瓜：萝卜"},{"label":"D","content":"男人：女人"}],"answer":"C","explanation":"逻辑学和光学为并列关系，两者都属于学科。<br>A项，芝士是奶酪(cheese)的音译名称，两者是全同关系，与题干关系不一致。<br>B项，教师和医生为交叉关系，与题干关系不一致。<br>C项，黄瓜和萝卜为并列关系，两者都属于蔬菜，与题干关系一致。<br>D项，男人和女人共同构成了人这个集合，除两者外不存在其他情况，因此男人和女人是矛盾关系，与题干关系不一致。","no":66},{"id":"1718789647597","type":"single","material":"","stem":"快餐：中式快餐：日式快餐","options":[{"label":"A","content":"团队：队长：队员"},{"label":"B","content":"行为：合法行为：非法行为"},{"label":"C","content":"颜色：黑色：白色"},{"label":"D","content":"体育课：音乐课：英语课"}],"answer":"C","explanation":"中式快餐和日式快餐是并列关系，两者都属于快餐，但还有其他种类的快餐<br>A项，队长和队员都是团队的组成部分，并非种属关系，与题干关系不一致。<br>B项，合法行为和非法行为都属于行为，除两者外不存在其他情况，因此两者为矛盾关系，与题干关系不一致。<br>C项，黑色和白色是并列关系，两者都属于颜色，但还有其他颜色，与题干关系一致。<br>D项，体育课、音乐课、英语课三者之间是并列关系，与题干关系不一致。","no":67},{"id":"1718789647598","type":"single","material":"","stem":"电视台对于（）相当于（）对于蚂蚁","options":[{"label":"A","content":"媒介;昆虫"},{"label":"B","content":"网络;工蚁"},{"label":"C","content":"电台;蟋蟀"},{"label":"D","content":"电视;蚁巢"}],"answer":"C","explanation":"代入A项，电视台属于媒介，蚂蚁属于昆虫，但前后位置颠倒，排除。<br>代入B项，电视台和网络都是传播媒介，两者是并列关系；工蚁属于蚂蚁，两者是种属关系，前后关系不一致。<br>代入C项，电视台和电台都是传播媒介，两者是并列关系；蟋蜂和蚂蚁都是昆虫，两者是并列关系，前后关系一致。<br>代入D项，电视台通过电视播放节目，蚁巢是蚂蚁的居住场所，前后关系不一致。","no":68},{"id":"1718789647599","type":"single","material":"","stem":"木材：抽屉：收纳","options":[{"label":"A","content":"钢铁：剪刀：切割"},{"label":"B","content":"棉花：毛线：保暖"},{"label":"C","content":"城墙：石头：防御"},{"label":"D","content":"橡胶：气垫：缓冲"}],"answer":"D","explanation":"木材是抽屉的原材料，抽屉的功能是收纳。<br>A项，剪刀的主要作用是剪，而非切割，与题干关系不一致。<br>B项，毛线的功能不是保暖，与题干关系不一致。<br>C项，石头是城墙的原材料，城墙的功能是防御，但词项位置颠倒。<br>D项，橡胶是气垫的原材料，气垫的功能是起缓冲作用，与题干关系一致。","no":69},{"id":"1718789647600","type":"single","material":"","stem":"寒冷：穿衣","options":[{"label":"A","content":"停机：话费"},{"label":"B","content":"漂亮：化妆"},{"label":"C","content":"生病：住院"},{"label":"D","content":"饥饿：吃饭"}],"answer":"D","explanation":"穿衣可以防止寒冷。<br>A项，充话费可以防止停机，而不是话费，与题干关系不一致。<br>B项，化妆可以让人变得漂亮，与题干关系不一致。<br>C项，生病了可能需要住院，与题干关系不一致。<br>D项，吃饭可以防止饥饿，与题干关系一致。","no":70},{"id":"1718789647601","type":"single","material":"","stem":"海水：澎湃","options":[{"label":"A","content":"西瓜：香甜"},{"label":"B","content":"道路：修建"},{"label":"C","content":"策划：推广"},{"label":"D","content":"平原：山林"}],"answer":"A","explanation":"澎湃可以形容海水。<br>A项，香甜可以形容西瓜，与题干关系一致。<br>B项，修建道路是动宾关系，与题干关系不一致。<br>C项，先策划后推广，二者是顺承关系，与题干关系不一致。<br>D项，平原和山林是并列关系，与题干关系不一致。","no":71},{"id":"1718789647602","type":"single","material":"","stem":"预习：上课：复习","options":[{"label":"A","content":"高考：考试：大学"},{"label":"B","content":"调研：设计：生产"},{"label":"C","content":"痊愈：挂号：出院"},{"label":"D","content":"笔试：面试：报名"}],"answer":"B","explanation":"先预习，再上课，最后复习。<br>A项，高考是一种考试，经过高考的选拔才能上大学，与题干关系不一致。B项，先调研，再设计，最后生产，是顺承关系，与题干关系一致。<br>C项，先挂号，经过治疗后痊愈，最后出院，选项顺序与题干不一致。<br>D项，一般是先报名，再笔试，最后面试，选项顺序与题干不一致。","no":72},{"id":"1718789647603","type":"single","material":"","stem":"<p>（ &nbsp; ）对于碧螺春相当于景德镇对于（ &nbsp; ）</p>","options":[{"label":"A","content":"苏州;瓷器"},{"label":"B","content":"宜兴；陶都"},{"label":"C","content":"茶叶;白瓷"},{"label":"D","content":"绿茶;锦都"}],"answer":"A","explanation":"A项，苏州出产碧螺春，景德镇出产瓷器。B项，宜兴和碧螺春没有明显的逻辑关系。C项，碧螺春是一种茶叶，与景德镇和白瓷的关系不一致。D项，代入后前后关系不一致。","no":73},{"id":"1718789647604","type":"single","material":"","stem":"U盘：光盘","options":[{"label":"A","content":"楼梯：电梯"},{"label":"B","content":"插头：插座"},{"label":"C","content":"国画：毛笔"},{"label":"D","content":"水杯：杯盖"}],"answer":"A","explanation":"U盘和光盘是两种不同的储存设备。<br>A项，楼梯和电梯是两种不同的上下楼设施，与题干关系一致。<br>B项，插头插在插座上，与题干关系不一致。<br>C项，用毛笔画国画，与题干关系不一致。<br>D项，杯盖是水杯的一部分，与题干关系不一致。","no":74},{"id":"1718789647605","type":"single","material":"","stem":"投票：抽签","options":[{"label":"A","content":"联系：沟通"},{"label":"B","content":"管理：服务"},{"label":"C","content":"劝说：争辩"},{"label":"D","content":"推荐：号召"}],"answer":"D","explanation":"投票是有目标的行为，抽签是随机行为。A项，联系和沟通都是有目标的行为，与题干关系不一致。B项，管理和服务都是有目标的行为，与题干关系不一致。<br>C项，劝说和争辩都是有目标的行为，与题干关系不一致。<br>D项，推荐是有目标的行为，号召是随机行为，与题干关系一致。","no":75},{"id":"1718789647606","type":"single","material":"","stem":"水：火","options":[{"label":"A","content":"美：丑"},{"label":"B","content":"有：无"},{"label":"C","content":"左：右"},{"label":"D","content":"红：绿"}],"answer":"D","explanation":"水和火是反对关系，但语义上不构成反义词。A项，美和丑在语义上是反义词，与题干关系不一致。<br>B项，有和无是矛盾关系，除两者外不存在其他情况，与题干关系不一致。C项，左和右在语义上是反义词，与题干关系不一致。<br>D项，红和绿是反对关系，但语义上不构成反义词，与题干关系一致。","no":76},{"id":"1718789647607","type":"single","material":"","stem":"雾霾：污染：治理","options":[{"label":"A","content":"风扇：电器：使用"},{"label":"B","content":"粳米：粮食：调查"},{"label":"C","content":"信息：报纸：阅读"},{"label":"D","content":"报告：文件：审批"}],"answer":"A","explanation":"雾霾是一种污染，治理污染。<br>A项，风扇是一种电器，使用电器，与题干关系一致。<br>B项，粳米是一种粮食，但调查和粮食不能构成动宾结构短语，与题干关系不一致。<br>C项，报纸上包含信息，阅读报纸，第一个词项与第二个词项不是种属关系，与题干关系不一致。<br>D项，报告和文件并不是种属关系，有些报告是文件，有些不是，两者是交叉关系，与题干关系不一致。","no":77},{"id":"1718789647608","type":"single","material":"","stem":"火柴：打火机：取火","options":[{"label":"A","content":"煤炉：燃气灶：煮饭"},{"label":"B","content":"锄头：马车：耕地"},{"label":"C","content":"镜子：梳子：梳妆"},{"label":"D","content":"皂角：浣纱：洗衣"}],"answer":"A","explanation":"火柴和打火机都可以用来取火，两者具有相同的功能。<br>A项，煤炉和燃气灶都可以用来煮饭，两者具有相同的功能，与题干关系一致。<br>B项，锄头可以耕地，但马车一般用来载人或运输货物，而非用来耕地，与题干关系不一致。<br>C项，镜子和梳子都是梳妆时需要的用具，两者的功能不同，与题干关系不一致。<br>D项，皂角可以用来浣纱和洗衣，与题干关系不一致。","no":78},{"id":"1718789647609","type":"single","material":"","stem":"养老保险：社会保障","options":[{"label":"A","content":"精准扶贫：粗放扶贫"},{"label":"B","content":"依法行政：依法治国"},{"label":"C","content":"精神文明：物质文明"},{"label":"D","content":"货币政策：财政政策"}],"answer":"B","explanation":"养老保险是社会保障的一部分。<br>A项，精准扶贫和粗放扶贫是扶贫的两种方式，两者是并列关系，与题干关系不一致。B项，依法行政是依法治国的一部分，与题干关系一致。<br>C项，精神文明和物质文明是并列关系，与题干关系不一致。<br>D项，货币政策和财政政策是国家宏观经济调控的两大基本政策手段，两者是并列关系，与题干关系不一致。","no":79},{"id":"1718789647610","type":"single","material":"","stem":"乡愁：落叶归根","options":[{"label":"A","content":"爱慕：一往情深"},{"label":"B","content":"豪迈：幅员辽阔"},{"label":"C","content":"贤良：沉鱼落雁"},{"label":"D","content":"勤劳：栉风沐雨"}],"answer":"A","explanation":"落叶归根比喻事物有一定的归宿，多指客居他乡的人终要回到本乡，有乡愁的情绪蕴含其中。<br>A项，一往情深指对人或对事物倾注了很深的感情，向往而不能克制，有爱慕的情绪蕴含其中，与题干关系一致。<br>B项，幅员辽阔指疆域辽阔，与豪迈并无必然联系，与题干关系不一致。<br>C项，沉鱼落雁形容女子容貌美丽，与贤良并无必然联系，与题干关系不一致。<br>D项，栉风沐雨形容人经常在外面不顾风雨地辛苦奔波，强调辛苦，与勤劳略有不同，与题干关系不一致。","no":80},{"id":"1718789647611","type":"single","material":"","stem":"煤炭：矿产：炼钢","options":[{"label":"A","content":"电影：艺术：投资"},{"label":"B","content":"钟乳石：景观：观赏"},{"label":"C","content":"火车：铁路：运输"},{"label":"D","content":"风力：能源：发电"}],"answer":"D","explanation":"煤炭是矿产的一种，可以用来炼钢。<br>A项，电影是艺术的一种，投资电影，构成动宾结构的短语，与题干关系不一致。<br>B项，钟乳石是景观的一种，观赏钟乳石，构成动宾结构的短语，与题干关系不一致。<br>C项，火车在铁路上运行，可以用来运输，与题干关系不一致。<br>D项，风力是能源的一种，可以用来发电，与题干关系一致。","no":81},{"id":"1718789647612","type":"single","material":"","stem":"无机物：化合物","options":[{"label":"A","content":"中草药：野菜"},{"label":"B","content":"二氧化碳：有机盐"},{"label":"C","content":"空间：时间"},{"label":"D","content":"原子：电子"}],"answer":"A","explanation":"无机物包括单质和无机化合物，化合物包括有机化合物和无机化合物，因此无机物和化合物是交叉关系。<br>A项，中草药中有部分属于野菜，野菜中有部分属于中草药，两者为交叉关系，与题干关系一致。<br>B项，有机盐是指含碳元素的盐类，二氧化碳不属于盐类，两者并非交叉关系，与题干关系不一致。<br>C项，空间与时间并非交叉关系，与题干关系不一致。<br>D项，原子中包含电子，但电子不包含原子，两者并非交叉关系，与题干关系不一致。","no":82},{"id":"1718789647613","type":"single","material":"","stem":"跳绳：运动","options":[{"label":"A","content":"花椒：调料"},{"label":"B","content":"开车：旅游"},{"label":"C","content":"太阳系：银河系"},{"label":"D","content":"水稻：米粉"}],"answer":"A","explanation":"跳绳是一种运动。<br>A项，花椒是一种调料，与题干关系一致。<br>B项，开车是旅游的一种方式，与题干关系不一致。<br>C项，银河系包含太阳系，与题干关系不一致。<br>D项，水稻和米粉的关系不同于题干词项间的关系。","no":83},{"id":"1718789647614","type":"single","material":"","stem":"雾霾对于（）相当于害虫对于（）","options":[{"label":"A","content":"天气;农田"},{"label":"B","content":"防范;防治"},{"label":"C","content":"污染;作物"},{"label":"D","content":"防尘;昆虫"}],"answer":"B","explanation":"A项，雾霾是一种天气，农田中有害虫，前后关系不一致。B项，防范雾霾，防治害虫，均为动宾关系。<br>C项，雾霾是一种污染，害虫危害作物，前后关系不一致。<br>D项，显然不存在对应关系。","no":84},{"id":"1718789647615","type":"single","material":"","stem":"分析对于（）相当于消除对于（）","options":[{"label":"A","content":"阐述;革新"},{"label":"B","content":"差距;贫富"},{"label":"C","content":"解决;创新"},{"label":"D","content":"问题;弊端"}],"answer":"D","explanation":"A项，分析之后进行阐述，消除和革新关系不一致。B项，不存在对应关系。<br>C项，分析和解决是并列关系，消除和创新与其关系不一致。<br>D项，分析问题，消除弊端，均为动宾关系。","no":85},{"id":"1718789647616","type":"single","material":"","stem":"前瞻：预见：回溯","options":[{"label":"A","content":"标新立异：特立独行：循规蹈矩"},{"label":"B","content":"犬牙交错：参差不齐：顺理成章"},{"label":"C","content":"墨守成规：井然有序：纷乱如麻"},{"label":"D","content":"深谋远虑：未雨绸缪：鼠目寸光"}],"answer":"A","explanation":"前瞻和预见是对未来的判断、预测，二者为近义关系；回溯是指回顾、回忆，和前两个词是反义关系。<br>A项，标新立异指提出新的主张、见解或创造出新奇的样式。特立独行泛指特殊的、与众不同的。二者为近义关系。循规蹈矩指拘守旧准则，不敢稍做变动，与前两个词为反义关系。<br>与题干关系一致。<br>B项，犬牙交错比喻交界线很曲折，也比喻情况复杂。参差不齐形容很不整齐或水平不一。顺理成章指情况合乎情理，自然产生某种结果。顺理成章和前两个词均不是反义关系。<br>C项，墨守成规意思是守着老规矩不肯改变。井然有序形容做某件事有条理。纷乱如麻指交错杂乱像一团乱麻。墨守成规和纷乱如麻不是反义关系。<br>D项，深谋远虑指计划得很周密，考虑得很长远。未雨绸缪比喻事先做好准备工作，预防意外的事发生。鼠目寸光比喻目光短浅，缺乏远见。未雨绸缪和鼠目寸光不是反义关系。","no":86},{"id":"1718789647617","type":"single","material":"","stem":"历练对于（）相当于磨砺对于（）","options":[{"label":"A","content":"栉风沐雨;千锤百炼"},{"label":"B","content":"千辛万苦;九死一生"},{"label":"C","content":"处心积虑;百折不回"},{"label":"D","content":"波澜不惊;一鸣惊人"}],"answer":"A","explanation":"A项，栉风沐雨可以形容历练，千锤百炼可以形容磨砺，前后关系一致。<br>B项，千辛万苦和九死一生与历练和磨砺无关。<br>C项，处心积虑不能形容历练。<br>D项，一鸣惊人不能形容磨砺。","no":87},{"id":"1718789647618","type":"single","material":"","stem":"黄连：苦涩","options":[{"label":"A","content":"花朵：鲜红"},{"label":"B","content":"钻石：坚硬"},{"label":"C","content":"城市：繁华"},{"label":"D","content":"班级：团结"}],"answer":"B","explanation":"黄连是苦涩的，苦涩是黄连的特点。<br>A项，花朵未必都是鲜红的，与题干关系不一致。<br>B项，钻石是坚硬的，坚硬是钻石的特点，与题干关系一致。<br>C项，城市未必都是繁华的，与题干关系不一致。<br>D项，班级未必都是团结的，与题干关系不一致。","no":88},{"id":"1718789647619","type":"single","material":"","stem":"麻雀：动物：生物链","options":[{"label":"A","content":"豆浆：早餐：豆制品"},{"label":"B","content":"开水：纸杯：便利品"},{"label":"C","content":"发卡：首饰：装扮品"},{"label":"D","content":"钢笔：电脑：办公品"}],"answer":"C","explanation":"麻雀是一种动物，动物属于生物链。<br>A项，豆浆属于早餐，但早餐和豆制品是交叉关系，而非包含关系，与题干关系不一致。<br>B项，用纸杯盛放开水，两者并非种属关系，与题干关系不一致。<br>C项，发卡是一种首饰，首饰属于装扮品，与题干关系一致。<br>D项，钢笔和电脑不是种属关系，与题干关系不一致。","no":89},{"id":"1718789647620","type":"single","material":"","stem":"（）对于熟练相当于敏捷对于（）","options":[{"label":"A","content":"熟悉;迅速"},{"label":"B","content":"操作;迅捷"},{"label":"C","content":"谙熟;灵动"},{"label":"D","content":"娴熟;灵敏"}],"answer":"D","explanation":"代入A项，熟悉指了解得清楚，清楚地知道；熟练指对技术精通而有经验，熟知并做来顺手。后者比前者的程度加深。敏捷和迅速是近义词，并没有体现程度加深。前后关系不一致。<br>代入B项，熟练地操作，两者为修饰关系；敏捷和迅捷是近义词。前后关系不一致。<br>代入C项，谙熟指熟悉，其与熟练为近义词；灵动指活泼不呆板，富于变化，其与敏捷不是近义词。前后关系不一致。<br>代入D项，娴熟和熟练为近义词，敏捷和灵敏为近义词。前后关系一致。","no":90},{"id":"1718789647621","type":"single","material":"","stem":"长度：厘米","options":[{"label":"A","content":"时间：钟表"},{"label":"B","content":"毫升：体积"},{"label":"C","content":"质量：千克"},{"label":"D","content":"速度：飞快"}],"answer":"C","explanation":"厘米是测量长度的单位。<br>A项，钟表可以显示时间，但钟表并不是单位，与题干关系不一致。<br>B项，毫升是体积的单位，但词项间顺序颠倒，与题干不一致。<br>C项，千克是测量质量的单位，与题干关系一致。<br>D项，速度飞快，飞快可以用来形容速度，但飞快并不是单位，与题干关系不一致。","no":91},{"id":"1718789647622","type":"single","material":"","stem":"太平洋：大西洋","options":[{"label":"A","content":"印度洋：印度"},{"label":"B","content":"黄海：南海"},{"label":"C","content":"月球：卫星"},{"label":"D","content":"萤火虫：昆虫"}],"answer":"B","explanation":"太平洋和大西洋都属于世界四大海洋，两者为并列关系。<br>A项，印度洋是海洋，印度是国家，两者并非并列关系，与题干关系不一致。<br>B项，黄海和南海都属于中国的四大海域，两者为并列关系，与题干关系一致。<br>C项，月球是一颗卫星，两者为包含关系，而非并列关系，与题干关系不一致。<br>D项，萤火虫属于昆虫，两者为包含关系，而非并列关系，与题干关系不一致。","no":92},{"id":"1718789647623","type":"single","material":"","stem":"惊涛骇浪：大海","options":[{"label":"A","content":"风和日丽：田野"},{"label":"B","content":"狼奔豕突：战役"},{"label":"C","content":"山崩地裂：灾害"},{"label":"D","content":"电闪雷鸣：天空"}],"answer":"D","explanation":"大海上惊涛骇浪，两者存在事物与发生位置的关系。<br>A项，风和日丽形容天气特别好，与田野不具有位置关系，与题干关系不一致。<br>B项，狼奔豕突形容成群的坏人乱冲乱撞，到处骚扰，与战役不具有位置关系，与题干关系不一致。<br>C项，山崩地裂是灾害的一种体现，两者并非位置关系，与题干关系不一致。<br>D项，天空中电闪雷鸣，两者存在事物与发生位置的关系，与题干关系一致。","no":93},{"id":"1718789647624","type":"single","material":"","stem":"熊掌：有力","options":[{"label":"A","content":"河马：彪悍"},{"label":"B","content":"鹰眼：犀利"},{"label":"C","content":"驼峰：耐力"},{"label":"D","content":"牛：勤劳"}],"answer":"B","explanation":"熊掌是熊的一个部位，有力是熊掌的特点。<br>A项，河马彪悍，但河马并非一个部位，与题干关系不一致。<br>B项，鹰眼是鹰的一个部位，犀利是鹰眼的特点，与题干关系一致。<br>C项，驼峰是骆驼的一个部位，但有耐力是骆驼的特点，而非驼峰的特点，与题干关系不一致。<br>D项，牛勤劳，但牛并非一个部位，与题干关系不一致。","no":94},{"id":"1718789647625","type":"single","material":"","stem":"实验舱对于（）相当于城楼对于（）","options":[{"label":"A","content":"资源舱;海市蜃楼"},{"label":"B","content":"运载火箭;砖瓦"},{"label":"C","content":"天宫一号;天安门"},{"label":"D","content":"发射;登高望远"}],"answer":"C","explanation":"代入A项，实验舱和资源舱是并列关系；海市蜃楼是一种自然现象，其与城楼不构成并列关系。前后关系不一致。<br>代入B项，运载火箭可以搭载实验舱，城楼由砖瓦组成。前后关系不一致。<br>代入C项，天宫一号是一个实验舱，天安门是一座城楼。前后关系一致。<br>代入D项，发射实验舱，构成动宾结构的短语；在城楼上登高望远，不构成动宾结构的短语。前后关系不一致。","no":95},{"id":"1718789647626","type":"single","material":"","stem":"清洁能源：太阳能","options":[{"label":"A","content":"女英雄：三八红旗手"},{"label":"B","content":"风车：风能"},{"label":"C","content":"可再生资源：植物"},{"label":"D","content":"治疗仪：按摩器"}],"answer":"C","explanation":"太阳能属于清洁能源，两者为种属关系。<br>A项，女英雄和三八红旗手是交叉关系，与题干关系不一致。<br>B项，风车需要用风能来提供动力，两者并非种属关系，与题干关系不一致。<br>C项，植物属于可再生资源，两者为种属关系，与题干关系一致。<br>D项，按摩器不一定可以治疗疾病，其与治疗仪之间并非种属关系，与题干关系不一致。","no":96},{"id":"1718789647627","type":"single","material":"","stem":"研究生：硕士：博士","options":[{"label":"A","content":"青少年：少年：青年"},{"label":"B","content":"妇孺：儿童：妇女"},{"label":"C","content":"建筑：平房：高楼"},{"label":"D","content":"图形：直线：三角形"}],"answer":"A","explanation":"研究生包括硕士和博士，在求学过程中，先读硕士，再读博士，两者具有时间先后顺序。<br>A项，青少年包括少年和青年，在成长过程中，先经历少年时期，再经历青年时期，两者具有时间先后顺序，与题干关系一致。<br>B项，妇孺包括妇女和儿童，但并非是儿童长大后就成了妇女，与题干关系不一致。C项，建筑包括平房和高楼，但两者不具有时间先后顺序，与题干关系不一致。<br>D项，图形包括直线和三角形，但两者不具有时间先后顺序，与题干关系不一致。","no":97},{"id":"1718789647628","type":"single","material":"","stem":"航空母舰对于（）相当于雷达对于（）","options":[{"label":"A","content":"驱逐舰;天线"},{"label":"B","content":"海洋;天空"},{"label":"C","content":"航载机;显示屏"},{"label":"D","content":"舰艇;电子设备"}],"answer":"D","explanation":"代入A项，航空母舰和驱逐舰是并列关系，天线是雷达的一部分。前后关系不一致。<br>代入B项，航空母舰在海洋上航行，但雷达并不是在天空中运行。前后关系不一致。<br>代入C项，航载机搭载在航空母舰上，两者存在位置关系；显示屏是雷达的组成部分。前后关系不一致。<br>代入D项，航空母舰是一种舰艇，雷达是一种电子设备。前后关系一致。","no":98},{"id":"1718789647629","type":"single","material":"","stem":"蜡烛：电灯","options":[{"label":"A","content":"椅子：写字台"},{"label":"B","content":"茶杯：饮水机"},{"label":"C","content":"拖把：吸尘器"},{"label":"D","content":"电视：计算机"}],"answer":"C","explanation":"蜡烛和电灯具有相同的功能，且电灯比蜡烛先进。<br>A项，椅子和写字台的功能不同，与题干关系不一致。<br>B项，茶杯和饮水机的功能不同，与题干关系不一致。<br>C项，拖把和吸尘器具有相同的功能，且吸尘器比拖把先进，与题干关系一致。D项，电视和计算机的功能不同，与题干关系不一致。","no":99},{"id":"1718789647630","type":"single","material":"","stem":"圈套：陷阱","options":[{"label":"A","content":"寡人：殿下"},{"label":"B","content":"文化：文明"},{"label":"C","content":"鸳鸯：蝴蝶"},{"label":"D","content":"高楼：大厦"}],"answer":"D","explanation":"圈套和陷阱为同义词。<br>A项，寡人为自称，殿下为他称。<br>B项，文化和文明并非同义关系。<br>C项，鸳鸯和蝴蝶是并列关系。<br>D项，高楼和大厦为同义词。","no":100},{"id":"1718789647631","type":"single","material":"","stem":"干旱：沙漠","options":[{"label":"A","content":"寒冷：南极"},{"label":"B","content":"多雨：赤道"},{"label":"C","content":"笔直：树干"},{"label":"D","content":"坚硬：水泥"}],"answer":"A","explanation":"沙漠的特点是干旱。<br>A项，南极的特点是寒冷。<br>B项，赤道既有多雨的雨林地区，也有干旱的沙漠地区，不符。<br>C项，树干并非都是笔直的。<br>D项，水泥凝固后才是坚硬的。","no":101},{"id":"1718789647632","type":"single","material":"","stem":"陈词滥调：老生常谈","options":[{"label":"A","content":"按部就班：循序渐进"},{"label":"B","content":"博闻强识：见多识广"},{"label":"C","content":"见义勇为：助人为乐"},{"label":"D","content":"八面玲珑：面面俱到"}],"answer":"D","explanation":"陈词滥调和老生常谈是近义词，且前者含贬义。<br>A项，按部就班和循序渐进意思不同。<br>B项，二者意思相近，但不存在贬义。<br>C项，二者意思不同，且均为褒义。<br>D项，八面玲珑和面面俱到是近义词，且前者含贬义。","no":102},{"id":"1718789647633","type":"single","material":"","stem":"火：烹饪","options":[{"label":"A","content":"雾：驾驶"},{"label":"B","content":"水：洗涤"},{"label":"C","content":"风：晴天"},{"label":"D","content":"磁：力量"}],"answer":"B","explanation":"火可以用来烹饪。<br>A项，雾会影响驾驶，与题干关系不一致。<br>B项，水可以用来洗涤，与题干关系一致。<br>C项，风和晴天没有明显的逻辑关系，与题干关系不一致。<br>D项，磁是力量的一种，与题干关系不一致。","no":103},{"id":"1718789647634","type":"single","material":"","stem":"歌曲对于（）相当于（）对于动作","options":[{"label":"A","content":"旋律;舞蹈"},{"label":"B","content":"歌手;交涉"},{"label":"C","content":"传唱;表现"},{"label":"D","content":"优美;夸张"}],"answer":"A","explanation":"A项，歌曲由旋律构成，舞蹈由动作构成，前后关系一致。<br>B项，歌曲由歌手演唱，交涉与动作没有明显逻辑关系，前后关系不一致。<br>C项，歌曲可以被传唱，动作是一种表现，前后关系不一致。<br>D项，优美可以形容歌曲，夸张可以形容动作，前后关系一致，但词项位置不一致。","no":104},{"id":"1718789647635","type":"single","material":"","stem":"得道多助：失道寡助","options":[{"label":"A","content":"骄兵必败：哀兵必胜"},{"label":"B","content":"不在其位：不谋其政"},{"label":"C","content":"吃一堑：长一智"},{"label":"D","content":"物以类聚：人以群分"}],"answer":"A","explanation":"得道多助和失道寡助是两种相反的情况。<br>A项，骄兵必败和哀兵必胜是两种相反的情况，与题干关系一致。<br>B项，因为不在其位，所以不谋其政，二者之间是因果关系，与题干关系不一致。<br>C项，因为吃一堑，所以长一智，二者之间是因果关系，与题干关系不一致。<br>D项，物以类聚指同类的东西聚在一起，人以群分指同类的人聚在一起，二者之间为近义关系，与题干关系不一致。","no":105},{"id":"1718789647636","type":"single","material":"","stem":"食言而肥：有言必诺","options":[{"label":"A","content":"有恩必报：忠君爱国"},{"label":"B","content":"坐井观天：勇往直前"},{"label":"C","content":"削足适履：因地制宜"},{"label":"D","content":"拾人牙慧：人云亦云"}],"answer":"C","explanation":"食言而肥指违背诺言，只图对自己有利；有言必诺指信守诺言，说过的话一定会做到。两者是一对反义词。<br>A项，有恩必报和忠君爱国并非反义词，与题干关系不一致。<br>B项，坐井观天比喻眼界狭窄或学识肤浅之人，其与勇往直前不构成反义关系，与题干关系不一致。<br>C项，削足适履比喻过分迁就现成条件，或生搬硬套；因地制宜指根据当地的实际情况，制定适当的措施。两者是一对反义词，与题干关系一致。<br>D项，拾人牙慧比喻抄袭或套用别人说过的话；人云亦云指没有主见，只会随声附和。两者是一对近义词，与题干关系不一致。","no":106},{"id":"1718789647637","type":"single","material":"","stem":"小麦：麦穗：麦粒","options":[{"label":"A","content":"车子：车轮：轮胎"},{"label":"B","content":"棋类：围棋：棋子"},{"label":"C","content":"学校：教室：学生"},{"label":"D","content":"房子：房间：卧室"}],"answer":"A","explanation":"麦粒是麦穗的一部分，麦穗是小麦的一部分。<br>A项，轮胎是车轮的一部分，车轮是车子的一部分，与题干关系一致。<br>B项，棋子是围棋的一部分，围棋属于棋类的一种，为种属关系，与题干关系不一致。C项，学生在教室里，教室在学校里，为位置关系，与题干关系不一致。<br>D项，卧室是房间的一种，为种属关系，房间是房子的一部分，与题干关系不一致。","no":107},{"id":"1718789647638","type":"single","material":"","stem":"上下：前后","options":[{"label":"A","content":"有无：朝暮"},{"label":"B","content":"左右：东西"},{"label":"C","content":"多少：正反"},{"label":"D","content":"异同：生死"}],"answer":"B","explanation":"上下、前后均为方位词，形容的是同一类事物，且每个词中两个字是反义关系。<br>A项，有和无、朝和暮是反义关系，但有无、朝暮并非形容同一类事物的词，与题干关系不一致，排除。<br>B项，左右、东西均为方位词，形容的是同一类事物，且每个词中两个字是反义关系，与题干关系一致。<br>C项，多和少、正和反是反义关系，但多少、正反并非形容同一类事物的词，与题干关系不一致，排除。<br>D项，异和同、生和死是反义关系，但异同、生死并非形容同一类事物的词，与题干关系不一致，排除。","no":108},{"id":"1718789647639","type":"single","material":"","stem":"学生：男学生：女学生","options":[{"label":"A","content":"旋转：顺时针：逆时针"},{"label":"B","content":"整数：正数：负数"},{"label":"C","content":"餐具：盘子：筷子"},{"label":"D","content":"词语：实词：虚词"}],"answer":"D","explanation":"男学生和女学生是矛盾关系，两者都属于学生。<br>A项，顺时针和逆时针是矛盾关系，但两者与旋转不构成种属关系，与题干关系不一致。<br>B项，正数和负数是反对关系，还有0的存在，与题干关系不一致。<br>C项，盘子和筷子是反对关系，两者都属于餐具，与题干关系不一致。<br>D项，实词和虚词是矛盾关系，两者都属于词语，与题干关系一致。","no":109},{"id":"1718789647640","type":"single","material":"","stem":"面粉：鸡蛋：蛋糕","options":[{"label":"A","content":"香蕉：西瓜：水果"},{"label":"B","content":"纸张：打印机：文件"},{"label":"C","content":"菊花：茱萸：重阳"},{"label":"D","content":"水泥：钢筋：房屋"}],"answer":"D","explanation":"面粉和鸡蛋是制作蛋糕的原材料。<br>A项，香蕉和西瓜都属于水果，为种属关系，与题干关系不一致。<br>B项，用打印机打印文件需要用到纸张，但打印机并非文件的原材料，与题干关系不一致。<br>C项，赏菊花、插茱萸是重阳节的活动，与题干关系不一致。<br>D项，水泥和钢筋是建造房屋的原材料，与题干关系一致。","no":110},{"id":"1718789647641","type":"single","material":"","stem":"小麦：馒头","options":[{"label":"A","content":"麋鹿：麝香"},{"label":"B","content":"叶绿体：细胞"},{"label":"C","content":"乌贼：墨汁"},{"label":"D","content":"棉花：布鞋"}],"answer":"D","explanation":"馒头由面粉加工而成，面粉可以由小麦加工而成。A项，麝香是从公麝鹿的身上得到的，而非麋鹿，与题干关系不一致。B项，叶绿体是细胞的组成部分，与题干关系不一致。<br>C项，乌贼与墨汁并非原材料关系，与题干关系不一致。<br>D项，布鞋由布加工而成，布可以由棉花加工而成，与题干关系一致。","no":111},{"id":"1718789647642","type":"single","material":"","stem":"春夏秋冬：四季","options":[{"label":"A","content":"喜怒哀乐：情绪"},{"label":"B","content":"赤橙黄绿：颜色"},{"label":"C","content":"早中晚：一天"},{"label":"D","content":"东南西北：四方"}],"answer":"D","explanation":"春夏秋冬构成了全部四季。<br>A项，情绪不只包含喜怒哀乐，还有其他情绪，与题干关系不一致。<br>B项，颜色不只包含赤橙黄绿，还有其他颜色，与题干关系不一致。<br>C项，一天不只包含早中晚，还有上午、下午等其他时间段，与题干关系不一致。<br>D项，东南西北构成了全部四方，与题干关系一致。","no":112},{"id":"1718789647643","type":"single","material":"","stem":"存折对于（）相当于栅栏对于（）","options":[{"label":"A","content":"储户;牛羊"},{"label":"B","content":"存款;绿地"},{"label":"C","content":"虚拟;实物"},{"label":"D","content":"银行卡;围墙"}],"answer":"D","explanation":"代入A项，储户有存折，牛羊在栅栏里。前后关系不一致。<br>代入B项，存折能体现出存款数量，栅栏与绿地并无必然联系。前后关系不一致。代入C项，存折并非虚拟的，栅栏是实物。前后关系不一致。<br>代入D项，存折和银行卡有同样的作用，栅栏和围墙有同样的作用。前后关系一致。","no":113},{"id":"1718789647644","type":"single","material":"","stem":"创新：僵化","options":[{"label":"A","content":"开放：闭塞"},{"label":"B","content":"发展：前进"},{"label":"C","content":"计划：秩序"},{"label":"D","content":"革新：失败"}],"answer":"A","explanation":"创新和僵化属于反义关系。<br>A项，开放和闭塞属于反义关系，与题干关系一致。<br>B项，发展和前进属于近义关系，与题干关系不一致。<br>C项，计划和秩序无明显关系，与题干关系不一致。<br>D项，革新有可能失败，与题干关系不一致。","no":114},{"id":"1718789647645","type":"single","material":"","stem":"生命：生物","options":[{"label":"A","content":"绿色：植物"},{"label":"B","content":"思维：人类"},{"label":"C","content":"收获：秋季"},{"label":"D","content":"节气：历法"}],"answer":"B","explanation":"生命是生物的一种特有属性。<br>A项，绿色并非植物的特有属性，与题干关系不一致。<br>B项，思维是人类的一种特有属性，与题干关系一致。<br>C项，收获并非秋季的特有属性，与题干关系不一致。<br>D项，节气是一种历法，与题干关系不一致。","no":115},{"id":"1718789647646","type":"single","material":"","stem":"<p>飞禽走兽：大雁：海鸥</p>","options":[{"label":"A","content":"珍馐美馔：山珍：海味"},{"label":"B","content":"花鸟鱼虫：鹦鹉：画眉"},{"label":"C","content":"锦衣玉食：蟒袍：霞帔"},{"label":"D","content":"卧虎藏龙：猛虎：蛟龙"}],"answer":"C","explanation":"飞禽走兽泛指鸟类和兽类两种事物，鸟类和兽类是的两个子类，大雁和海鸥是并列关系且都属于飞禽。A项，珍馐美馔泛指珍贵好吃的食物，山珍和海味是并列关系，但二者都是并列组成珍馐美馔的一种，与题干逻辑关系不一致。B项，花鸟鱼虫四种事物是并列关系，与题干逻辑关系不一致。C项，锦衣玉食泛指好的衣服和好的美食两种事物，锦衣和玉食是并列关系，蟒袍和霞帔是并列关系且都属于锦衣，与题干逻辑关系一致。D项，卧虎藏龙指隐藏着未被发现的人才或隐藏不露的人才，卧虎和藏龙是并列关系，猛虎和蛟龙是并列关系，但是分别属于卧虎和藏龙，与题干逻辑关系不一致。","no":116},{"id":"1718789647647","type":"single","material":"","stem":"纺车之于（）相当于（）之于联合收割机","options":[{"label":"A","content":"手摇;蒸汽机"},{"label":"B","content":"织布;传动带"},{"label":"C","content":"3D织布机;曲辕犁"},{"label":"D","content":"自动打线车;发动机"}],"answer":"C","explanation":"代入A项，纺车可以是手摇的，蒸汽机和联合收割机是不同的机器，两者为并列关系，前后关系不一致。<br>代入B项，纺车和织布并无明显联系，传动带是联合收割机的组成部分，前后关系不一致。<br>代入C项，纺车和3D织布机均属于纺织工具，曲辕犁和联合收割机均属于农用工具，且后者比前者先进。前后关系一致。<br>代入D项，纺车和自动打线车功能相似，发动机是联合收割机的组成部分，前后关系不一致。","no":117},{"id":"1718789647648","type":"single","material":"","stem":"罪犯：作案","options":[{"label":"A","content":"夫妻：结婚"},{"label":"B","content":"律师：辩论"},{"label":"C","content":"总统：出访"},{"label":"D","content":"员工：管理"}],"answer":"A","explanation":"作案是成为罪犯的必要条件。<br>A项，结婚是成为夫妻的必要条件，与题干关系一致。<br>B项，律师与辩论的关系不明显，不构成必要条件关系，与题干关系不一致。<br>C项，总统出访是主谓关系，与题干关系不一致。<br>D项，管理员工是动宾关系，与题干关系不一致。","no":118},{"id":"1718789647649","type":"single","material":"","stem":"蚊子：蚊帐：蚊香","options":[{"label":"A","content":"院子：木门：铁门"},{"label":"B","content":"暴雨：雨伞：雨衣"},{"label":"C","content":"窗户：窗纱：窗帘"},{"label":"D","content":"疾病：疫苗：病菌"}],"answer":"B","explanation":"蚊帐和蚊香是并列关系，两者都是为了防止被蚊子叮咬。<br>A项，木门和铁门都是门，两者为并列关系，但不能说木门和铁门是为了防院子，与题干关系不一致。<br>B项，雨伞和雨衣是并列关系，两者都是为了防止被暴雨淋湿，与题干关系一致。<br>C项，窗纱和窗帘是并列关系，但不能说窗纱和窗帘是为了防窗户，与题干关系不一致。<br>D项，某些病菌会导致疾病，疫苗可以预防疾病，与题干关系不一致。","no":119},{"id":"1718789647650","type":"single","material":"","stem":"（）对于轮船相当于电报对于（）","options":[{"label":"A","content":"竹筏;电话"},{"label":"B","content":"货轮;微信"},{"label":"C","content":"钢铁;通信方式"},{"label":"D","content":"发动机;传送信息"}],"answer":"A","explanation":"代入A项，竹筏和轮船都是水上运输工具，电报和电话都是通信工具，且后者比前者先进。前后关系一致。<br>代入B项，货轮是轮船的一种，两者为种属关系；电报和微信都是通信工具，两者为并列关系。前后关系不一致，排除。<br>代入C项，钢铁是制造轮船的原材料，电报是一种通信方式。前后关系不一致，排除。<br>代入D项，发动机是轮船的组成部分，电报可以用来传送信息。前后关系不一致，排除。","no":120},{"id":"1718789647651","type":"single","material":"","stem":"木鱼：带鱼：黄鱼","options":[{"label":"A","content":"虾米：小米：大米"},{"label":"B","content":"兵家：作家：画家"},{"label":"C","content":"桃子：橘子：房子"},{"label":"D","content":"荞麦：小麦：燕麦"}],"answer":"A","explanation":"木鱼不属于鱼类，带鱼和黄鱼都属于鱼类。<br>A项，虾米不属于谷物，小米和大米都属于谷物。<br>B项，兵家是古代诸子百家中研究兵法军事的一种流派，作家、画家是交叉关系。<br>C项，桃子和橘子是并列关系，都属于水果，房子不属于水果，但与题干位置不一致。<br>D项，荞麦、小麦、燕麦是并列关系，且都属于谷物。","no":121},{"id":"1718789647652","type":"single","material":"","stem":"送友人：折柳枝","options":[{"label":"A","content":"观花灯：猜谜语"},{"label":"B","content":"忆屈原：划龙舟"},{"label":"C","content":"闯关东：走西口"},{"label":"D","content":"画竹梅：明心志"}],"answer":"B","explanation":"送别时以折柳枝表达对友人的留念。<br>A项，在元宵节观花灯、猜谜语，两者是并列关系。<br>B项，端午节以划龙舟表达对屈原的怀念。<br>C项，走西口、闯关东是中国著名的两次人口迁移事件，二者是并列关系。<br>D项，古人常以画竹子、梅花来表明自己有骨气、高洁的品格，即以画竹梅来表明心志，与题干位置相反。","no":122},{"id":"1718789647653","type":"single","material":"","stem":"树：柏树：松树：雪松","options":[{"label":"A","content":"车：汽车：火车：动车"},{"label":"B","content":"法：刑法：民法：公民"},{"label":"C","content":"花：梅花：梨花：香梨"},{"label":"D","content":"牛：水牛：黄牛：牛黄"}],"answer":"A","explanation":"雪松是松树的一种，松树和柏树都是树。<br>A项，动车是火车的一种，火车和汽车都是车，与题干关系一致。<br>B项，刑法和民法都属于法，但公民是民法的管理对象，和民法不是种属关系，与题干关系不一致。<br>C项，梅花和梨花都属于花，但香梨是梨树的果实，和梨花不是种属关系，与题干关系不一致。<br>D项，水牛和黄牛都属于牛，但牛黄是牛身体里的一部分，和黄牛不是种属关系，与题干关系不一致。","no":123},{"id":"1718789647654","type":"single","material":"","stem":"旱田作物：粮食作物：高产作物","options":[{"label":"A","content":"工业酒精：食用酒精：医用酒精"},{"label":"B","content":"人民日报：光明日报：解放日报"},{"label":"C","content":"领军人物：新闻人物：公众人物"},{"label":"D","content":"脊椎动物：哺乳动物：高等动物"}],"answer":"C","explanation":"旱田作物、粮食作物、高产作物三者两两互为交叉关系。<br>A项，工业酒精、食用酒精、医用酒精是根据用途不同划分，三者为并列关系，与题干关系不同。<br>B项，人民日报、光明日报、解放日报为三份不同的报纸，三者为并列关系。<br>C项，领军人物、新闻人物、公众人物三者两两互为交叉关系，与题干关系相同。<br>D项，哺乳动物属于脊椎动物，高等动物属于脊椎动物，是种属关系，与题干关系不同。","no":124},{"id":"1718789647655","type":"single","material":"","stem":"清除之于（）相当于拔除之于（）","options":[{"label":"A","content":"垃圾;暗堡"},{"label":"B","content":"腐败;毒瘤"},{"label":"C","content":"路障;青苗"},{"label":"D","content":"积弊;垂柳"}],"answer":"B","explanation":"A项，清除垃圾，为动宾结构，但拔除和暗堡不能搭配，不符。<br>B项，清除腐败，拔除毒瘤。动宾关系，且都是消除不好的东西，符合。<br>C项，清除路障，拔除青苗。动宾关系，前后指意没有明显关系，不符。<br>D项，清除积弊，拔除垂柳。动宾关系，前后指意没有明显关系，不符。","no":125},{"id":"1718789647656","type":"single","material":"","stem":"缇萦救父：孝","options":[{"label":"A","content":"孔融让梨：义"},{"label":"B","content":"季札还愿：智"},{"label":"C","content":"毛遂自荐：礼"},{"label":"D","content":"尾生抱柱：信"}],"answer":"D","explanation":"缇萦救父讲述的是缇萦用她的毅力和勇气，四处奔走，使父亲含冤得雪，体现的是孝。微信公众号：免费分享<br>A项，孔融让梨讲述的是孔融小时候就知道把大个的梨让给哥哥吃，体现的是礼，而不是义，和题干关系不一致。<br>B项，季札还愿讲述的是季札出使各国，在徐国与国王徐公结下友谊，季札见徐公深爱自己的宝剑，心中默许出使回国时将剑赠与徐公。但季札回来时，徐公竟已经去世了。季札来到徐公安葬处，将宝剑摆放在墓前。体现的是信，而不是智，和题干关系不一致。<br>C项，毛遂自荐讲述的是赵国平原君的门客毛遂，自己举荐自己的故事。现比喻自告奋勇，自己推荐自己担任某项工作。体现的是勇，而不是礼，和题干关系不一致。<br>D项，尾生抱柱讲述的是尾生与女子约定在桥梁相会，久候女子不到，水涨，乃抱桥柱而死。一般用以比喻坚守信约。体现的是信，和题干关系一致。","no":126},{"id":"1718789647657","type":"single","material":"","stem":"竞争对于（）相当于关系对于（）","options":[{"label":"A","content":"竞赛;亲密"},{"label":"B","content":"残酷;关联"},{"label":"C","content":"比赛;疏远"},{"label":"D","content":"激烈;融洽"}],"answer":"D","explanation":"A项，竞赛是一种竞争，为种属关系；亲密的关系，为偏正结构。前后关系不一致。<br>B项，残酷的竞争，为偏正结构；关系和关联语义相近。前后关系不一致。<br>C项，比赛是一种竞争，为种属关系；疏远的关系，为偏正结构。前后关系不一致。<br>D项，激烈的竞争，为偏正结构；融洽的关系，为偏正结构。前后关系一致。","no":127},{"id":"1718789647658","type":"single","material":"","stem":"横看成岭侧成峰，远近高低各不同：江西：庐山","options":[{"label":"A","content":"白日依山尽，黄河入海流：山东：泰山"},{"label":"B","content":"会当凌绝顶，一览众山小：安徽：黄山"},{"label":"C","content":"长安回望绣成堆，山顶千门次第开：陕西：骊山"},{"label":"D","content":"画栋朝飞南浦云，珠帘暮卷西山雨：河南：嵩山"}],"answer":"C","explanation":"“横看成岭侧成峰，远近高低各不同”出自苏轼的《题西林壁》,描写的是江西庐山。<br>A项，“白日依山尽，黄河入海流”出自王之涣的《登鹳雀楼》,描写的是山西中条山，和题干关系不一致。<br>B项，“会当凌绝顶，一览众山小”出自杜甫的《望岳》,描写的是山东泰山，和题干关系不一致。<br>C项，“长安回望绣成堆，山顶千门次第开”出自杜牧的《过华清宫》,描写的是陕西骊山，和题干关系一致。<br>D项，“画栋朝飞南浦云，珠帘暮卷西山雨”出自王勃的《滕王阁诗》,描写的是江西滕王阁，和题干关系不一致。","no":128},{"id":"1718789647659","type":"single","material":"","stem":"路见不平：拔刀相助","options":[{"label":"A","content":"蛇鼠一窝：猫鼠同眠"},{"label":"B","content":"过街老鼠：人人喊打"},{"label":"C","content":"兴高采烈：喜气洋洋"},{"label":"D","content":"卧薪尝胆：扬眉吐气"}],"answer":"B","explanation":"因路见不平，而拔刀相助。<br>A项，蛇鼠一窝形容坏人互相勾结，或者形容两个相互关联的人做坏事的行径如出一辙；猫鼠同眠比喻官吏失职，包庇下属干坏事，也比喻上下狼狈为奸。二者为近义关系，和题干关系不一致。<br>B项，因是过街老鼠，而人人喊打，和题干关系一致。<br>C项，兴高采烈形容兴致高，精神饱满；喜气洋洋形容充满了欢喜的神色或气氛。二者为近义关系，和题干关系不一致。<br>D项，卧薪尝胆形容一个人忍辱负重，发愤图强，最终苦尽甘来；扬眉吐气形容摆脱了长期受压制状态后高兴痛快的样子。二者无明显关系，和题干关系不一致。","no":129},{"id":"1718789647660","type":"single","material":"","stem":"陆军：空军：作战","options":[{"label":"A","content":"播种机：收割机：农业"},{"label":"B","content":"汽车：轮船：运输"},{"label":"C","content":"超市：商场：促销"},{"label":"D","content":"法院：政府：司法"}],"answer":"B","explanation":"陆军和空军是两种不同的军种，两者是并列关系，其主要功能是作战。<br>A项，播种机和收割机是两种不同的农耕机械，但是它们的功能不是农业，排除。<br>B项，汽车和轮船是两种不同的交通工具，其主要功能是运输。与题干关系一致。<br>C项，超市和商场是两种不同的购物场所，但是它们的功能不是促销，排除。<br>D项，法院和政府是两个不同的机关，但是它们的功能不是司法，排除。","no":130},{"id":"1718789647661","type":"single","material":"","stem":"（）对于绿化相当于（）对于丰收","options":[{"label":"A","content":"种树;施肥"},{"label":"B","content":"美化;稻谷"},{"label":"C","content":"灌溉;收割"},{"label":"D","content":"园林;乡村"}],"answer":"A","explanation":"A项，种树有助于绿化，施肥有助于丰收，前后逻辑关系一致。<br>B项，绿化是美化的一种方式，稻谷丰收为主谓结构的短语，前后逻辑关系不一致，排除。<br>C项，绿化的过程中需要灌溉，丰收之后需要收割，前后逻辑关系不一致，排除。<br>D项，园林有绿化的作用，乡村和丰收没有类似的逻辑关系，排除。","no":131},{"id":"1718789647662","type":"single","material":"","stem":"空中乘务员：飞行员","options":[{"label":"A","content":"司机：交警"},{"label":"B","content":"学生：教师"},{"label":"C","content":"顾客：营业员"},{"label":"D","content":"护士：医生"}],"answer":"D","explanation":"空中乘务员和飞行员都是飞机上的工作人员。<br>A项，司机是交警的管理对象之一，二者不是在同一地点工作，和题干关系不一致。B项，学生是教师的教学对象，不是在学校工作的人，和题干关系不一致。<br>C项，顾客是营业员的服务对象，不是一种职业，和题干关系不一致。<br>D项，护士和医生都是医院里的工作人员，和题干关系一致。","no":132},{"id":"1718789647663","type":"single","material":"","stem":"耿耿于怀：牵肠挂肚","options":[{"label":"A","content":"敲山震虎：打草惊蛇"},{"label":"B","content":"旷古绝伦：无独有偶"},{"label":"C","content":"工力悉敌：旗鼓相当"},{"label":"D","content":"望洋兴叹：易如反掌"}],"answer":"C","explanation":"耿耿于怀形容令人牵挂或不愉快的事在心里难以排解；牵肠挂肚形容非常挂念，很不放心。二者都形容一直惦记着某事，是近义关系。<br>A项，敲山震虎指故意示警，使人震动；打草惊蛇比喻采取机密行动时，不慎惊动了对方。二者不是近义关系，和题干关系不一致。<br>B项，旷古绝伦意为空前未有，超出一般；无独有偶指虽然罕见，但是不只一个，还有一个可以成对儿(多用于贬义)。二者为反义关系，和题干关系不一致。<br>C项，工力悉敌形容双方用的功夫和力量相当，常形容两个优秀的艺术作品不分上下；旗鼓相当比喻双方力量不相上下。二者都形容实力基本一致，是近义关系，和题干关系一致。<br>D项，望洋兴叹比喻要做一件事而力量不够，感到无可奈何；易如反掌比喻事情极容易办。二者不是近义关系，和题干关系不一致。","no":133},{"id":"1718789647664","type":"single","material":"","stem":"《骆驼祥子》:《四世同堂》","options":[{"label":"A","content":"《呐喊》:《雷雨》"},{"label":"B","content":"《土门》:《秦腔》"},{"label":"C","content":"《红与黑》:《老人与海》"},{"label":"D","content":"《国富论》:《资本论》"}],"answer":"B","explanation":"《骆驼祥子》和《四世同堂》都是老舍的作品。<br>A项，《呐喊》的作者是鲁迅，《雷雨》的作者是曹禺，和题干关系不一致。<br>B项，《土门》和《秦腔》都是贾平凹的作品，和题干关系一致。<br>C项，《红与黑》的作者是司汤达，《老人与海》的作者是海明威，和题干关系不一致。<br>D项，《国富论》的作者是亚当·斯密，《资本论》的作者是卡尔·马克思，和题干关系不一致。","no":134},{"id":"1718789647665","type":"single","material":"","stem":"肺腑之言对于（）相当于（）对于艰苦","options":[{"label":"A","content":"诚实;风尘仆仆"},{"label":"B","content":"真诚;风餐露宿"},{"label":"C","content":"诚信;千锤百炼"},{"label":"D","content":"忠诚;风吹雨打"}],"answer":"B","explanation":"A项，肺腑之言意思是发自内心的真诚的话，和诚实无明显关系；风尘仆仆形容旅途辛苦劳累，和艰苦无明显关系。前后关系不一致。<br>B项，肺腑之言意思是发自内心的真诚的话，表示真诚；风餐露宿形容旅途或野外生活的艰苦，表示艰苦。前后关系一致。<br>C项，肺腑之言意思是发自内心的真诚的话，和诚信无明显关系；千锤百炼比喻多次的斗争和考验，可表示艰苦。前后关系不一致。<br>D项，肺腑之言意思是发自内心的真诚的话，和忠诚无明显关系；风吹雨打比喻恶势力对弱者的迫害，或严峻的考验，可表示艰苦。前后关系不一致。","no":135},{"id":"1718789647666","type":"single","material":"","stem":"有形损耗：无形损耗","options":[{"label":"A","content":"中国哲学：西方哲学"},{"label":"B","content":"蒸馏酒：葡萄酒"},{"label":"C","content":"急性中毒：慢性中毒"},{"label":"D","content":"有色金属：稀有金属"}],"answer":"C","explanation":"损耗分为有形损耗和无形损耗，二者为绝对反义关系。<br>A项，中国哲学和西方哲学之外还有其他哲学，二者为相对反义关系，与题干关系不一致。<br>B项，有些葡萄酒是蒸馏酒，二者是交叉关系，与题干关系不一致。<br>C项，中毒分为急性中毒和慢性中毒，二者是绝对反义关系，与题干关系一致。<br>D项，有色金属和稀有金属是交叉关系，与题干关系不一致。","no":136},{"id":"1718789647667","type":"single","material":"","stem":"大豆：酱油","options":[{"label":"A","content":"柠檬：白醋"},{"label":"B","content":"淀粉：年糕"},{"label":"C","content":"花生：香油"},{"label":"D","content":"甘蔗：红糖"}],"answer":"D","explanation":"大豆是制作酱油的主要原料。<br>A项，柠檬不是制作白醋的原料，与题干关系不一致。<br>B项，年糕的主要成分是淀粉，与题干关系不一致。<br>C项，花生也不是香油的原料，与题干关系不一致。<br>D项，甘蔗是制作红糖的主要原料，与题干关系一致。","no":137},{"id":"1718789647668","type":"single","material":"","stem":"小斑虎猫：虎猫属：猫科","options":[{"label":"A","content":"庄稼：粮食：谷物"},{"label":"B","content":"卷尺：尺子：工具"},{"label":"C","content":"小学：初中：高中"},{"label":"D","content":"少尉：少校：少将"}],"answer":"B","explanation":"小斑虎猫属于虎猫属，虎猫属属于猫科。<br>A项，庄稼指种在地里的粮食作物，属于粮食；谷物也属于粮食，与题干关系不一致。B项，卷尺属于尺子，尺子属于工具，与题干关系一致。<br>C项，小学、初中、高中是并列关系，与题干关系不一致。<br>D项，少尉、少校、少将是并列关系，与题干关系不一致。","no":138},{"id":"1718789647669","type":"single","material":"","stem":"我：认识：你","options":[{"label":"A","content":"八：大于：六"},{"label":"B","content":"你：矮于：她"},{"label":"C","content":"尔：就是：你"},{"label":"D","content":"他：喜欢：她"}],"answer":"D","explanation":"我认识你是主谓宾结构，“我”和“你”是人称代词，“认识”是动词。<br>A项，八大于六不是主谓宾结构，与题干关系不一致。<br>B项，你矮于她是主谓宾结构，“你”和“她”是人称代词，“矮于”是状语，与题干关系不一致。<br>C项，尔就是你是主谓宾结构，“尔”和“你”是人称代词，“就是”是副词，与题干关系不一致。<br>D项，他喜欢她是主谓宾结构，“他”和“她”是人称代词，“喜欢”是动词，与题干关系一致。","no":139},{"id":"1718789647670","type":"single","material":"","stem":"声母：韵母：声调","options":[{"label":"A","content":"本体：喻体：喻词"},{"label":"B","content":"车轮：车胎：车门"},{"label":"C","content":"满族：汉族：白族"},{"label":"D","content":"比拟：拟人：拟物"}],"answer":"A","explanation":"声母和韵母为并列关系，二者和声调共同构成音节。<br>A项，本体和喻体为并列关系，二者和喻词共同构成比喻句，和题干关系一致。<br>B项，车轮包含车胎，二者和车门构不成车，和题干关系不一致。<br>C项，满族、汉族和白族为并列关系，和题干关系不一致。<br>D项，比拟包含拟人和拟物，和题干关系不一致。","no":140},{"id":"1718789647671","type":"single","material":"","stem":"（）对于冶炼相当于创作对于（）","options":[{"label":"A","content":"矿物;作者"},{"label":"B","content":"选矿;发表"},{"label":"C","content":"工人;作品"},{"label":"D","content":"提纯;表演"}],"answer":"B","explanation":"A项，矿物是冶炼的客体，作者是创作的主体，前后关系不一致。<br>B项，先选矿才能冶炼，先创作才能发表，前后关系一致。<br>C项，工人是冶炼的主体，作品是创作的客体，前后关系不一致。<br>D项，冶炼的目的是提纯，创作的目的是表演，前后关系不一致。","no":141},{"id":"1718789647672","type":"single","material":"","stem":"市场行为：购买：销售","options":[{"label":"A","content":"修辞：夸张：排比"},{"label":"B","content":"思想家：孔子：政治家"},{"label":"C","content":"飞机：汽车：轮船"},{"label":"D","content":"无机物：硫铁矿：氨基酸"}],"answer":"A","explanation":"市场行为包含购买和销售，购买和销售是并列关系。<br>A项，修辞包含夸张和排比，夸张和排比是并列关系，与题干关系一致。<br>B项，思想家包含孔子，思想家和政治家是交叉关系，与题干关系不一致。<br>C项，飞机、汽车和轮船是并列关系，与题干关系不一致。<br>D项，无机物组成硫铁矿，氨基酸不属于无机物，与题干关系不一致。","no":142},{"id":"1718789647673","type":"single","material":"","stem":"招标：中标","options":[{"label":"A","content":"宣传：推广"},{"label":"B","content":"请示：批复"},{"label":"C","content":"抽象：具体"},{"label":"D","content":"支出：收入"}],"answer":"B","explanation":"招标之后才能中标，两者存在时间先后顺序。<br>A项，宣传和推广没有时间先后顺序，与题干关系不一致，排除。<br>B项，请示之后才能批复，两者存在时间先后顺序，与题干关系一致。<br>C项，抽象和具体是反义关系，与题干关系不一致，排除。<br>D项，支出未必要先有收入，与题干关系不一致，排除。","no":143},{"id":"1718789647674","type":"single","material":"","stem":"听证会对于（）相当于（）对于职工","options":[{"label":"A","content":"证人;运动会"},{"label":"B","content":"专家;职代会"},{"label":"C","content":"领导;展览会"},{"label":"D","content":"居民;家长会"}],"answer":"B","explanation":"听证会是一种把司法审判的模式引入行政和立法程序的制度。听证会模拟司法审判，由意见相反的双方互相辩论，其结果通常对最后的处理有拘束力。<br>代入A项，证人是司法审判的参与人员，而非听证会的参与人员，两者之间没有必然联系。职工可能参加运动会。前后关系不一致，排除。<br>代入B项，专家是听证会的主要参与者，职工是职代会的主要参与者。前后关系一致。<br>代入C项，听证会与领导没有必然联系，职工可能参加展览会。前后关系不一致，排除。<br>代入D项，居民可能参加听证会。职工和家长会之间没有必然联系，家长才是家长会的主要参与者，而非职工。前后关系不一致，排除。","no":144},{"id":"1718789647675","type":"single","material":"","stem":"豆：黄豆：四季豆","options":[{"label":"A","content":"瓜：西瓜：佛手瓜"},{"label":"B","content":"果：糖果：罗汉果"},{"label":"C","content":"茶：奶茶：乌龙茶"},{"label":"D","content":"油：酱油：绵羊油"}],"answer":"A","explanation":"黄豆和四季豆是并列关系，都属于豆。<br>A项，西瓜和佛手瓜是并列关系，都属于瓜。与题干关系一致。<br>B项，糖果并不是一种果，罗汉果属于果。与题干关系不一致，排除。<br>C项，奶茶并不是一种茶，茶是奶茶的原材料，乌龙茶属于茶。与题干关系不一致，排除。<br>D项，酱油是一种调味品，绵羊油是一种从天然羊毛中精炼出来的油脂，两者都不属于油。与题干关系不一致，排除。","no":145},{"id":"1718789647676","type":"single","material":"","stem":"拐弯抹角对于（）相当于（）对于富有","options":[{"label":"A","content":"直接;家徒四壁"},{"label":"B","content":"委婉;穷困潦倒"},{"label":"C","content":"直白;家财万贯"},{"label":"D","content":"清楚;富可敌国"}],"answer":"A","explanation":"代入A项，拐弯抹角比喻说话绕弯，不直截了当。拐弯抹角与直接是反义关系。家徒四壁形容家中十分贫穷，空无所有。家徒四壁与富有是反义关系。前后关系一致。<br>代入B项，拐弯抹角与委婉是近义关系。穷困潦倒形容生活贫困，失意颓丧。穷困潦倒与富有是反义关系。前后关系不一致，排除。<br>代入C项，拐弯抹角与直白是反义关系，家财万贯与富有是近义关系。前后关系不一致，排除。<br>代入D项，拐弯抹角与清楚不具有近反义关系，富可敌国与富有是近义关系。前后关系不一致，排除。","no":146},{"id":"1718789647677","type":"single","material":"","stem":"平邮：快递","options":[{"label":"A","content":"经济舱：头等舱"},{"label":"B","content":"普快列车：高铁"},{"label":"C","content":"短信：微信"},{"label":"D","content":"信件：传真"}],"answer":"B","explanation":"平邮和快递都是一种邮寄方式，且快递比平邮快。<br>A项，头等舱和经济舱是同一飞机的两种座位，且二者不存在速度的差异，与题干关系不一致。<br>B项，普通列车和高铁都是出行工具，且高铁比普快列车速度快，与题干关系一致。C项，短信和微信都是一种通信方式，但二者的速度无法比较，与题干关系不一致。<br>D项，信件是指书信和递送的文件、印刷品；传真是利用光电效应，通过有线电或无线电装置把照片、图表、书信、文件等的真迹传送到远方的通信方式，二者是两种不同的传递方式，与题干关系不一致。","no":147},{"id":"1718789647678","type":"single","material":"","stem":"孑了：蚊子","options":[{"label":"A","content":"树苗：杨树"},{"label":"B","content":"羊羔：绵羊"},{"label":"C","content":"蝌蚪：青蛙"},{"label":"D","content":"麦种：小麦"}],"answer":"C","explanation":"孑了是蚊子的幼体，孑了成长为蚊子是变态发育。<br>A项，树苗能够长成大树，但并不一定长成杨树，且树苗成长不是变态发育，与题干关系不一致。<br>B项，羊羔不一定长成绵羊，且羊羔的成长不是变态发育，与题干关系不一致。<br>C项，蝌蚪是青蛙的幼体，蝌蚪成长为青蛙是变态发育，与题干关系一致。<br>D项，麦种是小麦的种子，但麦种长成麦子不是变态发育，与题干关系不一致。","no":148},{"id":"1718789647679","type":"single","material":"","stem":"序幕：尾声","options":[{"label":"A","content":"散文：戏剧"},{"label":"B","content":"方言：粤语"},{"label":"C","content":"元音：辅音"},{"label":"D","content":"进士：状元"}],"answer":"A","explanation":"序幕和尾声都是同一事件或作品的一部分，且还有其他部分，二者为反对关系。<br>A项，散文和戏剧是文学体裁的一种，且还存在其他文学体裁，二者是反对关系，与题干关系一致。<br>B项，粤语是方言的一种，二者是种属关系，与题干关系不一致。<br>C项，元音和辅音都是音素的一类，但音素只包括元音和辅音，二者是矛盾关系，与题干关系不一致。<br>D项，古代科举殿试录取三甲，一甲三名，赐“进士及第”的称号，第一名称状元，二者是种属关系，与题干关系不一致。","no":149},{"id":"1718789647680","type":"single","material":"","stem":"（）对于小说相当于琴弦对于（）","options":[{"label":"A","content":"写实;音乐"},{"label":"B","content":"浪漫;乐器"},{"label":"C","content":"情节;竖琴"},{"label":"D","content":"诗歌;吉他"}],"answer":"C","explanation":"代入A项，写实是小说写作风格的一种，由琴弦组成的乐器可以弹奏<br>音乐，前后关系不一致。<br>代入B项，小说有的是浪漫的，有些乐器由琴弦组成，前后关系不一致。<br>代入C项，情节是小说的一部分，琴弦是竖琴的一部分，均为组成关系，前后关系一致。<br>代入D项，诗歌和小说为并列关系，琴弦是吉他的组成部分，前后关系不一致。","no":150},{"id":"1718789647681","type":"single","material":"","stem":"成百：上千","options":[{"label":"A","content":"三教：九流"},{"label":"B","content":"三头：六臂"},{"label":"C","content":"千变：万化"},{"label":"D","content":"千方：百计"}],"answer":"C","explanation":"成百和上千说的都是数量多，且后者比前者多。<br>A项，三教九流是古代中国对人的地位和职业名称划分的等级。三教指儒教、道教、佛教；九流指儒家、道家、阴阳家、法家、名家、墨家、纵横家、杂家、农家。两者的含义不同，与题干关系不一致。<br>B项，三头六臂比喻神通广大，本领出众。三头是指三个脑袋；六臂是指六条胳膊。两者的含义不同，与题干关系不一致。<br>C项，千变和万化说的都是变化多，且后者大于前者，与题干关系一致。<br>D项，千方和百计说的都是方法、计谋多，但后者小于前者，与题干关系不一致。","no":151},{"id":"1718789647682","type":"single","material":"","stem":"寒：寒冷：寒舍","options":[{"label":"A","content":"甘：甘甜：甘愿"},{"label":"B","content":"恨：仇恨：怨恨"},{"label":"C","content":"肤：皮肤：肌肤"},{"label":"D","content":"讽：讽刺：讥讽"}],"answer":"A","explanation":"题干后两个词均含有“寒”字，但表示的意思不同。“寒冷”中的“寒”表示“冷”,“寒舍”中的“寒”表示“穷困”。<br>A项，后两个词均含有“甘”字，但表示的意思不同。“甘甜”中的“甘”表示“甜、味道好”,“甘愿”中的“甘”表示“自愿、乐意”,与题干关系一致。<br>B项，后两个词均含有“恨”字，但含义相同，都表示“对人或事物怀有强烈的敌对或不满的感情”,与题干关系不一致。<br>C项，后两个词均含有“肤”字，但含义相同，都表示“肉体表面的皮”,与题干关系不<br>一致。<br>D项，后两个词均含有“讽”字，但含义相同，都表示“用含蓄的话指责或劝告”,与题干关系不一致。","no":152},{"id":"1718789647683","type":"single","material":"","stem":"儿童：女童：未成年","options":[{"label":"A","content":"房屋：桥梁：建筑"},{"label":"B","content":"小狗：狗崽：犬"},{"label":"C","content":"佐料：酱油：调料"},{"label":"D","content":"植物油：椰子油：菜籽油"}],"answer":"B","explanation":"女童属于儿童，儿童属于未成年。<br>A项，房屋和桥梁是并列关系，与题干关系不一致。<br>B项，狗崽属于小狗，小狗属于犬，与题干关系一致。<br>C项，佐料包含调料，与题干关系不一致。<br>D项，椰子油和菜籽油是并列关系，与题干关系不一致。","no":153},{"id":"1718789647684","type":"single","material":"","stem":"储存：光盘：硬盘","options":[{"label":"A","content":"晾晒：绳索：衣架"},{"label":"B","content":"吃饭：钢叉：锅铲"},{"label":"C","content":"书写：签字笔：毛笔"},{"label":"D","content":"游泳：泳圈：泳衣"}],"answer":"C","explanation":"光盘和硬盘的主要功能都是储存。<br>A项，绳索的主要功能不是晾晒，与题干关系不一致。<br>B项，锅铲的主要功能不是吃饭，与题干关系不一致。<br>C项，签字笔和毛笔的主要功能都是书写，与题干关系一致。<br>D项，泳衣的主要功能不是游泳，与题干关系不一致。","no":154},{"id":"1718789647685","type":"single","material":"","stem":"为虎添翼：如虎添翼","options":[{"label":"A","content":"耸人听闻：骇人听闻"},{"label":"B","content":"一字不差：一字不落"},{"label":"C","content":"无所不至：无所不知"},{"label":"D","content":"好为人师：善为人师"}],"answer":"D","explanation":"为虎添翼指替老虎加上翅膀，比喻帮助坏人，增加恶人的势力，是贬义词；如虎添翼指如同老虎长了翅膀，比喻强大的事物更加强大了，是褒义词。<br>A项，耸人听闻指夸大或捏造事实，使人听了感到惊异或震动；骇人听闻指使人听了某事后感到很惊讶、恐惧。二者属于近义关系，不存在明显的褒贬关系，与题干关系不一致。<br>B项，一字不差指一个字也没有更改；一字不落指整篇文章都仔细逐字逐句地阅读或背诵，一个字也不落下。二者不存在明显的褒贬关系，与题干关系不一致。<br>C项，无所不至指没有达不到的地方，无明显褒贬含义，与题干关系不一致。<br>D项，好为人师形容不谦虚，自以为是，是贬义词；善为人师指善于指导别人，是褒义词。与题干关系一致。","no":155},{"id":"1718789647686","type":"single","material":"","stem":"<p>水对于（ &nbsp; ）相当于（ &nbsp; ）对于光合作用</p>","options":[{"label":"A","content":"生命;二氧化碳"},{"label":"B","content":"水蒸气；阳光"},{"label":"C","content":"空气;氧气"},{"label":"D","content":"灌溉;土壤"}],"answer":"A","explanation":"A项，生命离不开水，光合作用离不开二氧化碳，前后关系一致。B项，水可以变成水蒸气，阳光参与光合作用，前后关系不一致。C项，空气和水都是生物生存的必要条件，二者为并列关系，氧气是光合作用的产物，前后关系不一致。D项，水可以灌溉，土壤不参与光合作用，前后关系不一致。","no":156},{"id":"1718789647687","type":"single","material":"","stem":"（）对于规划相当于鸿沟对于（）","options":[{"label":"A","content":"城市;协调"},{"label":"B","content":"计划;河流"},{"label":"C","content":"成功;隔阂"},{"label":"D","content":"蓝图;界限"}],"answer":"D","explanation":"A项，城市建设需要规划，鸿沟和协调不具有明显关系，前后关系不<br>一致。<br>B项，计划和规划是近义关系，河流和鸿沟不具有明显关系，前后关系不一致。<br>C项，成功需要规划，鸿沟是巨大的隔阂，前后关系不一致。<br>D项，蓝图可以比喻规划，鸿沟可以比喻界限，前后关系一致。","no":157},{"id":"1718789647688","type":"single","material":"","stem":"鸿雁：笺札：书信","options":[{"label":"A","content":"月老：红娘：媒人"},{"label":"B","content":"乾坤：天地：宇宙"},{"label":"C","content":"红豆：相思：恋人"},{"label":"D","content":"东宫：王子：储君"}],"answer":"A","explanation":"鸿雁、笺札都代指书信。<br>A项，月老、红娘都代指媒人，与题干关系一致。<br>B项，乾坤代指天地，不能代指宇宙，与题干关系不一致。<br>C项，红豆代指相思，相思不能代指恋人，与题干关系不一致。<br>D项，王子不能代指储君，与题干关系不一致。","no":158},{"id":"1718789647689","type":"single","material":"","stem":"茶树：茉莉花茶","options":[{"label":"A","content":"梅树：梅花糕"},{"label":"B","content":"小麦：肉夹馍"},{"label":"C","content":"螃蟹：蟹黄包"},{"label":"D","content":"冬瓜：冬瓜糖"}],"answer":"C","explanation":"茉莉花茶的部分材料是茶叶，茶叶是茶树的一部分。<br>A项，梅花糕是形状像梅花的糕点，其材料中并不含有梅花，与题干关系不一致。<br>B项，肉夹馍的部分材料是面粉，面粉不是小麦的一部分，与题干关系不一致。<br>C项，蟹黄包的部分材料是蟹黄，蟹黄是螃蟹的一部分，与题干关系一致。<br>D项，冬瓜糖的部分材料是冬瓜，但是是冬瓜整体，与题干关系不一致。","no":159},{"id":"1718789647690","type":"single","material":"","stem":"盲动：一败涂地：重起炉灶","options":[{"label":"A","content":"超速：风驰电掣：按部就班"},{"label":"B","content":"跟风：鹦鹉学舌：真知灼见"},{"label":"C","content":"熬夜：萎靡不振：养精蓄锐"},{"label":"D","content":"传神：生动逼真：洛阳纸贵"}],"answer":"C","explanation":"盲动可能会导致一败涂地，一败涂地后需要重起炉灶。<br>A项，风驰电掣不是超速导致的结果，与题干关系不一致。<br>B项，鹦鹉学舌可以形容跟风，与题干关系不一致。<br>C项，熬夜可能会导致萎靡不振，萎靡不振时需要养精蓄锐，与题干关系一致。<br>D项，生动逼真可以形容传神，与题干关系不一致。","no":160},{"id":"1718789647691","type":"single","material":"","stem":"番茄之于（）相当于（）之于蹴鞠","options":[{"label":"A","content":"美洲;中国"},{"label":"B","content":"炒饭;健身"},{"label":"C","content":"植物;人类"},{"label":"D","content":"白菜;篮球"}],"answer":"D","explanation":"A项，番茄起源于美洲，蹴鞠起源于中国，前后关系一致，但前后词项位置不一致。<br>B项，番茄可以用来炒饭，蹴鞠可以用来健身，前后关系一致，但前后词项位置不一致。<br>C项，番茄属于植物，人类可以玩蹴鞠，前后关系不一致。<br>D项，番茄和白菜是并列关系，都是蔬菜的一种；篮球和蹴鞠(足球)是并列关系，都是球类的一种，前后关系一致。","no":161},{"id":"1718789647692","type":"single","material":"","stem":"（）之于精当相当于固若金汤之于（）","options":[{"label":"A","content":"瑕瑜互见;牢靠"},{"label":"B","content":"字字珠玑;防御"},{"label":"C","content":"无懈可击;城池"},{"label":"D","content":"不刊之论;坚实"}],"answer":"D","explanation":"A项，瑕瑜互见与精当之间没有明显关系，固若金汤与牢靠是近义关系，前后关系不一致。<br>B项，字字珠玑与精当之间没有明显关系，固若金汤可以形容防御，前后关系不一致。<br>C项，无懈可击与精当之间没有明显关系，固若金汤的形容对象可以为城池，前后关系不一致。<br>D项，不刊之论与精当是近义关系，固若金汤与坚实是近义关系，前后关系一致。","no":162},{"id":"1718789647693","type":"single","material":"","stem":"虚数：复数","options":[{"label":"A","content":"法律：刑法"},{"label":"B","content":"麦子：水稻"},{"label":"C","content":"祥林嫂：《祝福》"},{"label":"D","content":"人工智能：计算机科学"}],"answer":"D","explanation":"虚数是复数的一部分。<br>A项，刑法是法律的一部分，与题干关系一致，但词项前后位置不一致。<br>B项，麦子和水稻是并列关系，与题干关系不一致。<br>C项，祥林嫂是《祝福》中的主要人物，与题干关系不一致。<br>D项，人工智能是计算机科学的一个分支，与题干关系一致。","no":163},{"id":"1718789647694","type":"single","material":"","stem":"爸爸：叔父：兄弟","options":[{"label":"A","content":"哥哥：婶婶：夫妻"},{"label":"B","content":"奶奶：姑姑：子女"},{"label":"C","content":"姨妈：伯伯：兄妹"},{"label":"D","content":"妈妈：嫂子：婆媳"}],"answer":"D","explanation":"爸爸和叔父是兄弟关系。<br>A项，哥哥和婶婶不是夫妻关系，与题干关系不一致。<br>B项，奶奶和姑姑不是子女关系，与题干关系不一致。<br>C项，姨妈和伯伯不是兄妹关系，与题干关系不一致。<br>D项，妈妈和嫂子是婆媳关系，与题干关系一致。","no":164},{"id":"1718789647695","type":"single","material":"","stem":"刻舟求剑：拔苗助长","options":[{"label":"A","content":"望梅止渴：守株待兔"},{"label":"B","content":"闻鸡起舞：缘木求鱼"},{"label":"C","content":"宾至如归：闭门造车"},{"label":"D","content":"掩耳盗铃：南辕北辙"}],"answer":"D","explanation":"刻舟求剑、拔苗助长均表示仅以个人主观为意志而忽略客观事实，由错误的行为导致了不好的结果。<br>A项，望梅止渴比喻用空想来安慰自己，没有涉及忽略客观事实，与题干关系不一致。<br>B项，闻鸡起舞比喻有志报国的人及时奋起，没有涉及忽略客观事实，与题干关系不一致。<br>C项，宾至如归形容接待客人热情周到，没有涉及忽略客观事实，与题干关系不一致。<br>D项，掩耳盗铃和南辕北辙均表示仅以个人主观为意志而忽略客观事实，由错误的行为导致了不好的结果，与题干关系一致。","no":165},{"id":"1718789647696","type":"single","material":"","stem":"鱼：潜水艇","options":[{"label":"A","content":"蜈蚣：火车"},{"label":"B","content":"飞机：鸟"},{"label":"C","content":"虾：汽车"},{"label":"D","content":"蝙蝠：雷达"}],"answer":"D","explanation":"潜水艇是模仿鱼的浮沉原理发明的。<br>A项，火车的行驶不是模仿蜈蚣发明的，与题干关系不一致。<br>B项，飞机的飞行是模仿鸟的飞行原理发明的，与题干关系一致，但词项前后位置不一致。<br>C项，虾和汽车之间没有明显关系，与题干关系不一致。<br>D项，雷达是模仿蝙蝠的探测原理发明的，与题干关系一致。","no":166},{"id":"1718789647697","type":"single","material":"","stem":"少先队员对于（）相对于警察对于（）","options":[{"label":"A","content":"红领巾;警帽"},{"label":"B","content":"校服;警徽"},{"label":"C","content":"孩子;警员"},{"label":"D","content":"纪律;治安"}],"answer":"A","explanation":"A项，红领巾是少先队员的标识，警帽是警察的标识，前后关系一致。B项，少先队员穿校服，警察佩戴警徽，前后关系不一致。<br>C项，孩子包含少先队员，警察包含警员，前后关系一致，但前后词项位置不一致。<br>D项，少先队员要遵守纪律，警察要维护治安，前后关系不一致。","no":167},{"id":"1718789647698","type":"single","material":"","stem":"园：园中园","options":[{"label":"A","content":"楼：楼外楼"},{"label":"B","content":"人：梦中人"},{"label":"C","content":"月：水中月"},{"label":"D","content":"画：画中画"}],"answer":"D","explanation":"园(林)里面可以有园中园。<br>A项，楼外楼并不在楼中，与题干关系不一致。<br>B项，梦中人并不在人中，与题干关系不一致。<br>C项，水中月并不在月中，与题干关系不一致。<br>D项，画(作)里面可以有画中画，与题干关系一致。","no":168},{"id":"1718789647699","type":"single","material":"","stem":"人去：楼空","options":[{"label":"A","content":"鸟尽：弓藏"},{"label":"B","content":"兽聚：鸟散"},{"label":"C","content":"鸢飞：鱼跃"},{"label":"D","content":"虎踞：龙盘"}],"answer":"A","explanation":"人去楼空的意思是人已离去，楼中空空。比喻故地重游时睹物思人的感慨。因人去而楼空，两者之间为因果关系。<br>A项，鸟尽弓藏的意思是鸟打完了把弓藏起来。比喻事情成功之后，把曾经出过力的人一脚踢开，过河拆桥。因鸟尽而弓藏，两者之间为因果关系，与题干关系一致。<br>B项，兽聚鸟散的意思是像鸟兽一样时聚时散。比喻聚散无常，也比喻乌合之众。两者之间并没有因果关系，与题干关系不一致。<br>C项，鸢飞鱼跃的意思是鹰在天空飞翔，鱼在水中腾跃。形容万物各得其所。两者之间是并列关系，而非因果关系，与题干关系不一致。<br>D项，虎踞龙盘形容地势雄伟险要。两者之间是并列关系，而非因果关系，与题干关系不一致。","no":169},{"id":"1718789647700","type":"single","material":"","stem":"《大学》:《中庸》:四书","options":[{"label":"A","content":"泰山：华山：五岳"},{"label":"B","content":"物欲：财欲：六欲"},{"label":"C","content":"朝夕：除夕：七夕"},{"label":"D","content":"春风：秋雨：四季"}],"answer":"A","explanation":"四书指的是《大学》《中庸》《论语》《孟子》,因此《大学》《中庸》均属于四书。微信公众号：免费分享<br>A项，五岳指的是东岳泰山、西岳华山、南岳衡山、北岳恒山和中岳嵩山，因此泰山和华山均属于五岳。与题干关系一致。<br>B项，六欲包括眼(见欲)、耳(听欲)、鼻(香欲)、舌(味欲)、身(触欲)、意(意欲),物欲和财欲均不属于六欲。与题干关系不一致。<br>C项，朝夕指天天、时时，也指非常短的时间；除夕和七夕都属于节日。与题干关系不一致。<br>D项，春和秋属于四季，而非春风、秋雨属于四季，春风和秋雨为并列关系。与题干关系不一致。","no":170},{"id":"1718789647701","type":"single","material":"","stem":"中山陵：金陵","options":[{"label":"A","content":"城隍庙：寺庙"},{"label":"B","content":"青海湖：青海"},{"label":"C","content":"碧云天：青天"},{"label":"D","content":"钱塘江：长江"}],"answer":"B","explanation":"中山陵位于金陵(今南京)。<br>A项，城隍庙是道教庙宇，与寺庙是种属关系，与题干关系不一致。<br>B项，青海湖位于青海，与题干关系一致。<br>C项，碧云天和青天均指晴天，两者不存在位置关系，与题干关系不一致。<br>D项，钱塘江和长江是并列关系，与题干关系不一致。","no":171},{"id":"1718789647702","type":"single","material":"","stem":"文物：建筑","options":[{"label":"A","content":"烹饪：佐料"},{"label":"B","content":"故宫：楼房"},{"label":"C","content":"诗人：教授"},{"label":"D","content":"皮鞋：布鞋"}],"answer":"C","explanation":"文物和建筑是交叉关系。<br>A项，烹饪需要用佐料，两者之间不是交叉关系。<br>B项，故宫中有楼房，即楼房是故宫的组成部分，两者之间是组成关系，不是交叉关系。<br>C项，诗人和教授是交叉关系，与题干关系一致。<br>D项，皮鞋和布鞋是并列关系，不是交叉关系。","no":172},{"id":"1718789647703","type":"single","material":"","stem":"眼睛：鼻子：五官","options":[{"label":"A","content":"西湖：东湖：五湖"},{"label":"B","content":"五律：五绝：五言诗"},{"label":"C","content":"父子：夫妇：五伦"},{"label":"D","content":"五音：五色：五线谱"}],"answer":"C","explanation":"五官指眉、眼、耳、鼻、口，即五官包含眼睛和鼻子。<br>A项，五湖在近代一般指洞庭湖、鄱阳湖、太湖、巢湖、洪泽湖。古代的说法不同，如《国语》《史记》中的五湖专指太湖，或太湖及其附近的湖泊。因此该项中的五湖不包含西湖、东湖，与题干关系不一致。<br>B项，五言诗是古代诗歌体裁之一，约起源于西汉而在东汉末年趋于成熟。初唐以后，产生了近体诗，其中就有五言律诗、五言绝句。唐代以前的五言诗便通称为“五言古诗”或“五古”。因此该项中的五言诗不包含五律、五绝，与题干关系不一致。<br>C项，五伦指君臣、父子、兄弟、夫妇、朋友五种人伦关系，即五伦包含父子、夫妇关系，与题干关系一致。<br>D项，五音指宫、商、角、徵、羽，五色指青、黄、赤、白、黑，五线谱是乐谱。因此该项中的五线谱不包含五音、五色，与题干关系不一致。","no":173},{"id":"1718789647704","type":"single","material":"","stem":"电流强度：安培","options":[{"label":"A","content":"功率：伏特"},{"label":"B","content":"电阻：欧姆"},{"label":"C","content":"电荷：瓦特"},{"label":"D","content":"压强：牛顿"}],"answer":"B","explanation":"电流强度的单位是安培。<br>A项，功率的单位是瓦特，伏特是电压的单位，与题干关系不一致，排除。<br>B项，电阻的单位是欧姆，与题干关系一致。<br>C项，电荷的单位是库伦，瓦特是功率的单位，与题干关系不一致，排除。<br>D项，压强的单位是帕斯卡，牛顿是力的单位，与题干关系不一致，排除。","no":174},{"id":"1718789647705","type":"single","material":"","stem":"失之毫厘：谬以千里","options":[{"label":"A","content":"三十六计：走为上计"},{"label":"B","content":"招之即来：挥之即去"},{"label":"C","content":"种瓜得瓜：种豆得豆"},{"label":"D","content":"前人栽树：后人乘凉"}],"answer":"D","explanation":"因“失之毫厘”而“谬以千里”,两者是因果关系。<br>A项，“走为上计”是“三十六计”的组成部分，两者并非因果关系，与题干关系不一致。<br>B项，“招之即来”和“挥之即去”是并列关系，两者并非因果关系，与题干关系不<br>一致。<br>C项，“种瓜得瓜”和“种豆得豆”是并列关系，两者并非因果关系，与题干关系不<br>一致。<br>D项，因“前人栽树”而“后人乘凉”,两者是因果关系，与题干关系一致。","no":175},{"id":"1718789647706","type":"single","material":"","stem":"熟石灰：Ca(OH)₂","options":[{"label":"A","content":"钡餐：BaSO₄"},{"label":"B","content":"纯碱：NaHCO₃"},{"label":"C","content":"CO₂:干冰"},{"label":"D","content":"生石灰：CaCO₃"}],"answer":"A","explanation":"熟石灰的主要成分是Ca(OH)₂。<br>A项，钡餐的主要成分为是BaSO₄,与题干关系一致。<br>B项，纯碱的化学式是Na₂CO₃,与题干关系不一致。<br>C项，干冰的化学式是CO₂,与题干关系一致，但词项前后顺序不一致。<br>D项，生石灰的化学式是CaO,与题干关系不一致。","no":176},{"id":"1718789647707","type":"single","material":"","stem":"（）对于月食相当于（）对于日食","options":[{"label":"A","content":"太阳；地球"},{"label":"B","content":"太阳；月亮"},{"label":"C","content":"地球；月亮"},{"label":"D","content":"火星；地球"}],"answer":"C","explanation":"A项，太阳发出光线但是光线没有照射到月球，产生月食，太阳发出光线但是光线没有照射到地球产生日食，前后关系不一致。<br>B项，太阳发出光线但是光线没有照射到月球，产生月食，太阳发出光线被月球挡住，没有照射到地球，产生日食，前后关系不一致。<br>C项，因为地球在太阳和月球之间而产生月食，因为月亮在太阳和地球之间而产生日食，均因为前者的位置而产生了后者的自然现象，前后关系一致。<br>D项，火星和月食之间无明显的逻辑关系，而太阳发出光线但是光线没有照射到地球产生日食，前后关系不一致。","no":177},{"id":"1718789647708","type":"single","material":"","stem":"上衣：领袖","options":[{"label":"A","content":"兄弟：手足"},{"label":"B","content":"时间：岁月"},{"label":"C","content":"身体：耳目"},{"label":"D","content":"动物：鹰犬"}],"answer":"C","explanation":"领袖是上衣的一部分，也可以指能为人表率的人或者是国家、政党、群众团体等的最高领导人。<br>A项，手足象征兄弟，与题干关系不同。<br>B项，岁月代表时间，与题干关系不同。<br>C项，耳目是身体的一部分，也可以指监视人或为别人收集情报者，与题干关系一致。<br>D项，鹰和犬均是动物的一种，为种属关系，与题干关系不同。","no":178},{"id":"1718789647709","type":"single","material":"","stem":"作茧自缚：化蛹成蝶","options":[{"label":"A","content":"灯蛾扑火：化羽归尘"},{"label":"B","content":"雨润花开：春华秋实"},{"label":"C","content":"鱼翔浅底：鹰击长空"},{"label":"D","content":"凤凰浴火：涅槃重生"}],"answer":"D","explanation":"蚕作茧自缚后才能化蛹成蝶。<br>A项，灯蛾扑火和化羽归尘，与题干关系不一致。<br>B项，雨润花开和春华秋实，与题干关系不一致。<br>C项，鱼翔浅底和鹰击长空是并列关系，与题干关系不一致。<br>D项，凤凰浴火后才能涅槃重生，和题干关系一致。","no":179},{"id":"1718789647710","type":"single","material":"","stem":"川菜：素菜：热菜","options":[{"label":"A","content":"格律诗：唐诗：五言诗"},{"label":"B","content":"黄金：液体：导体"},{"label":"C","content":"电器：通信工具：电话"},{"label":"D","content":"鱼：水生动物：爬行动物"}],"answer":"A","explanation":"川菜可以是素菜和热菜，素菜可以是川菜和热菜，热菜可以是川菜和素菜。<br>A项，格律诗可以是唐诗和五言诗，唐诗可以是格律诗和五言诗，五言诗可以是唐诗和格律诗，与题干关系一致。<br>B项，黄金不是液体，与题干关系不一致。<br>C项，电话是一种通信工具，两者是包含关系，与题干关系不一致。<br>D项，鱼是一种水生动物，两者是包含关系，与题干关系不一致。","no":180},{"id":"1718789647711","type":"single","material":"","stem":"多多益善：韩信：刘邦","options":[{"label":"A","content":"卧薪尝胆：勾践：西施"},{"label":"B","content":"乐不思蜀：刘禅：司马昭"},{"label":"C","content":"四面楚歌：张良：项羽"},{"label":"D","content":"莫须有：韩世忠：秦桧"}],"answer":"B","explanation":"典故多多益善涉及的主要人物是韩信和刘邦。<br>A项，典故卧薪尝胆涉及的主要人物是夫差和勾践，不是西施，与题干关系不一致。B项，典故乐不思蜀涉及的主要人物是刘禅和司马昭，与题干关系一致。<br>C项，典故四面楚歌涉及的主要人物是项羽，不是张良，与题干关系不一致。<br>D项，典故莫须有涉及的主要人物是岳飞和秦桧，不是韩世忠，与题干关系不一致。","no":181},{"id":"1718789647712","type":"single","material":"","stem":"<p>教师对于（ &nbsp; ）相当于（ &nbsp; ）对于厨房</p>","options":[{"label":"A","content":"课堂；厨师"},{"label":"B","content":"书桌；卧室"},{"label":"C","content":"学生；餐厅"},{"label":"D","content":"学校；顾客"}],"answer":"A","explanation":"A项，教师的工作地点是课堂，厨师的工作地点是厨房，前后关系一致。B项，书桌是教师的办公工具，卧室和厨房均是房子里的一部分，前后关系不一致。C项，教师教授学生知识，餐厅和厨房均是房子里的一部分，前后关系不一致。D项，教师在学校工作，顾客和厨房关系不明显，前后关系不一致。","no":182},{"id":"1718789647713","type":"single","material":"","stem":"证券：债券","options":[{"label":"A","content":"山水画：人物画"},{"label":"B","content":"油画：壁画"},{"label":"C","content":"绘画：素描"},{"label":"D","content":"漫画：年画"}],"answer":"C","explanation":"债券是一种有价证券，两者是种属关系。<br>A项，山水画和人物画是并列关系，与题干关系不一致，排除。<br>B项，油画和壁画是并列关系，与题干关系不一致，排除。<br>C项，素描是一种绘画，两者是种属关系，与题干关系一致。<br>D项，漫画和年画是并列关系，与题干关系不一致，排除。","no":183},{"id":"1718789647714","type":"single","material":"","stem":"海啸：地震","options":[{"label":"A","content":"天亮：鸡鸣"},{"label":"B","content":"高血压：血压计"},{"label":"C","content":"中毒：蘑菇"},{"label":"D","content":"沙滩：阳光"}],"answer":"C","explanation":"地震可能引起海啸。<br>A项，天亮时会有鸡鸣，并不是鸡鸣引起天亮，与题干关系不一致。<br>B项，血压计可以测量出高血压，并不是血压计引起高血压，与题干关系不一致。<br>C项，蘑菇可能引起中毒，与题干关系一致。<br>D项，沙滩和阳光之间不存在因果关系，与题干关系不一致。","no":184},{"id":"1718789647715","type":"single","material":"","stem":"芒果对于（）相当于（）对于砂糖","options":[{"label":"A","content":"芒果核；麦芽糖"},{"label":"B","content":"芒果汁；甜菜"},{"label":"C","content":"水果；食糖"},{"label":"D","content":"泰国芒；棒棒糖"}],"answer":"B","explanation":"代入A项，芒果核是芒果的一部分，麦芽糖和砂糖是并列关系，前后关系不一致，排除。<br>代入B项，芒果可以用来制作芒果汁，甜菜可以用来制作砂糖，前后关系一致。<br>代入C项，芒果是一种水果，砂糖是一种食糖，但前后位置颠倒，排除。<br>代入D项，泰国芒是一种芒果，砂糖是制作棒棒糖的原料，前后关系不一致，排除。","no":185},{"id":"1718789647716","type":"single","material":"","stem":"作品：文字作品：摄影作品","options":[{"label":"A","content":"人身权：姓名权：肖像权"},{"label":"B","content":"糖果：棒棒糖：水果糖"},{"label":"C","content":"科学：自然科学：经济学"},{"label":"D","content":"面食：面条：重庆小面"}],"answer":"A","explanation":"文字作品和摄影作品是并列关系，两者都属于作品。<br>A项，姓名权和肖像权是并列关系，两者都属于人身权，与题干关系一致。<br>B项，棒棒糖和水果糖是交叉关系，两者都属于糖果，与题干关系不一致。<br>C项，经济学属于社会科学，自然科学和社会科学是并列关系，所以自然科学和经济学并不是同一级别的概念，两者不是并列关系，与题干关系不一致。<br>D项，重庆小面属于面条，面条属于面食，与题干关系不一致。","no":186},{"id":"1718789647717","type":"single","material":"","stem":"端午节：吃粽子","options":[{"label":"A","content":"元宵节：元宵"},{"label":"B","content":"中秋节：赏月"},{"label":"C","content":"重阳节：游湖"},{"label":"D","content":"除夕：守岁"}],"answer":"B","explanation":"吃粽子是端午节的一种习俗。<br>A项，元宵节的习俗是吃元宵，而不是元宵，与题干关系不一致。<br>B项，中秋节的习俗是赏月，月亮是一种实物，与题干关系一致。<br>C项，重阳节的习俗是登高，而不是游湖，与题干关系不一致。<br>D项，除夕的习俗是守岁，而守岁不是一种实物，与题干关系不一致。","no":187},{"id":"1718789647718","type":"single","material":"","stem":"七窍生烟：气愤","options":[{"label":"A","content":"同流合污：腐败"},{"label":"B","content":"哀鸿遍野：荒凉"},{"label":"C","content":"琴瑟和鸣：恩爱"},{"label":"D","content":"高雅脱俗：骄傲"}],"answer":"C","explanation":"七窍生烟形容焦急或干渴之极，好像耳目口鼻都冒火，可以形容气愤。A项，同流合污指跟着坏人一起做坏事，不可以形容腐败，与题干关系不一致。<br>B项，哀鸿遍野形容到处都是呻吟呼号、流离失所的灾民的悲惨景象，不可以形容荒凉，与题干关系不一致。<br>C项，琴瑟和鸣比喻夫妇情笃和好，可以形容恩爱，与题干关系一致。<br>D项，高雅脱俗指高尚优雅脱离凡俗，不可以形容骄傲，与题干关系不一致。","no":188},{"id":"1718789647719","type":"single","material":"","stem":"（）对于折射相当于杯弓蛇影对于（）","options":[{"label":"A","content":"一叶障目；透射"},{"label":"B","content":"小孔成像；衍射"},{"label":"C","content":"碧空如洗；散射"},{"label":"D","content":"海市蜃楼；反射"}],"answer":"D","explanation":"海市蜃楼是光线折射形成的，杯弓蛇影是光线反射形成的。<br>A项的一叶障目和B项的小孔成像的原理都是光沿直线传播，与折射无关。<br>C项，碧空如洗的原理是光的散射。","no":189},{"id":"1718789647720","type":"single","material":"","stem":"春暖：花开","options":[{"label":"A","content":"和风：细雨"},{"label":"B","content":"雨后：天晴"},{"label":"C","content":"天寒：地冻"},{"label":"D","content":"云开：雾散"}],"answer":"C","explanation":"因春暖而花开，两者具有因果关系。<br>A项，和风和细雨是并列关系，并非因果关系，与题干关系不一致。<br>B项，雨后并不是天晴的原因，与题干关系不一致。<br>C项，因天寒而地冻，两者是因果关系，与题干关系一致，且春暖花开和天寒地冻是反义词。<br>D项，云开和雾散是并列关系，并非因果关系，与题干关系不一致。","no":190},{"id":"1718789647721","type":"single","material":"","stem":"言论：自由","options":[{"label":"A","content":"版权：保护"},{"label":"B","content":"危机：调控"},{"label":"C","content":"生产：安全"},{"label":"D","content":"设计：创新"}],"answer":"C","explanation":"自由的言论，自由修饰言论。<br>A项，保护版权，构成动宾结构短语，与题干关系不一致。<br>B项，调控危机，构成动宾结构短语，与题干关系不一致。<br>C项，安全地生产，安全修饰生产，与题干关系一致。<br>D项，创新设计，构成动宾结构短语，与题干关系不一致。","no":191},{"id":"1718789647722","type":"single","material":"","stem":"好感：喜欢：热爱","options":[{"label":"A","content":"伤心：悲伤：悲哀"},{"label":"B","content":"不安：紧张：焦躁"},{"label":"C","content":"不悦：反感：厌恶"},{"label":"D","content":"高兴：愉快：喜悦"}],"answer":"B","explanation":"好感、喜欢、热爱是近义词，并且词义程度逐渐加重。<br>A项，伤心、悲伤、悲哀是近义词，但不存在明显的词义程度加重的情况，与题干关系不一致。<br>B项，不安、紧张和焦躁是近义词，并且词义程度逐渐加重，与题干关系一致。<br>C项，不悦的意思是不高兴，而不是不喜欢，其与反感、厌恶并不是近义词，与题干关系不一致。<br>D项，高兴、愉快、喜悦是近义词，但不存在明显的词义程度加重的情况，与题干关系不一致。","no":192},{"id":"1718789647723","type":"single","material":"","stem":"蜡烛：电灯","options":[{"label":"A","content":"算盘：计算机"},{"label":"B","content":"信鸽：电报机"},{"label":"C","content":"鞭炮：火枪"},{"label":"D","content":"电视：电影"}],"answer":"A","explanation":"蜡烛和电灯都是人造的照明工具，两者的功能相同。<br>A项，算盘和计算机都是人造的计算工具，两者的功能相同，与题干关系一致。<br>B项，信鸽和电报机都能传送信息，但信鸽是动物，并非人造的工具，与题干关系不一致，排除。<br>C项，鞭炮和火枪的功能不同，与题干关系不一致，排除。<br>D项，在电视上放映电影，与题干关系不一致，排除。","no":193},{"id":"1718789647724","type":"single","material":"","stem":"太阳对于（）相当于（）对于相机","options":[{"label":"A","content":"手表；倒影"},{"label":"B","content":"能源；科技"},{"label":"C","content":"烛光；胶卷"},{"label":"D","content":"向日葵；望远镜"}],"answer":"A","explanation":"代入A项，手表是根据日晷针影随太阳运转而变化的原理制作的，相机是根据小孔成像的倒影原理制作的。前后关系一致。<br>代入B项，太阳可以提供能源，科技与相机之间并无类似关系。前后关系不一致。代入C项，太阳和烛光都可以照明，胶卷是相机的一部分。前后关系不一致。<br>代入D项，向日葵的生长离不开太阳，望远镜和相机是两种设备，两者是并列关系。前后关系不一致。","no":194},{"id":"1718789647725","type":"single","material":"","stem":"大同小异：大相径庭：差异","options":[{"label":"A","content":"举世无双：比比皆是：人才"},{"label":"B","content":"背信弃义：恪守不渝：信任"},{"label":"C","content":"东施效颦：邯郸学步：模仿"},{"label":"D","content":"高瞻远瞩：鼠目寸光：视野"}],"answer":"D","explanation":"大同小异指大体相同，略有差异。大相径庭指相差很远，大不相同。两者是反义词，都是形容差异的。<br>A项，举世无双指世界上再没有第二个这样的人或物，形容极其罕见稀有。比比皆是指到处都是，形容极其常见。两者是反义词，但并非形容人才，与题干关系不一致。<br>B项，背信弃义指违背诺言，不讲道义。恪守不渝指严格遵守，决不改变。两者是反义词，但并非形容信任，与题干关系不一致。<br>C项，东施效颦比喻模仿别人，不但模仿不好，反而出丑。邯郸学步比喻生搬硬套，机械地模仿别人，不但学不到别人的长处，反而会把自己的优点和本领也丢掉。两者是近义词，都是形容模仿的，与题干关系不一致。<br>D项，高瞻远瞩指站得高，看得远，比喻眼光远大。鼠目寸光比喻目光短浅，缺乏远见。两者是反义词，都是形容视野的，与题干关系一致。","no":195},{"id":"1718789647726","type":"single","material":"","stem":"海拔：等高线","options":[{"label":"A","content":"设计：作品"},{"label":"B","content":"电阻：电压"},{"label":"C","content":"音量：振幅"},{"label":"D","content":"涨幅：价格"}],"answer":"C","explanation":"等高线可以表示海拔高度。<br>A项，设计作品，构成动宾结构的短语，与题干关系不一致。<br>B项，电压并不能表示电阻大小，与题干关系不一致。<br>C项，振幅可以表示音量大小，与题干关系一致。<br>D项，价格有涨幅，但价格并不能表示涨幅大小，与题干关系不一致。","no":196},{"id":"1718789647727","type":"single","material":"","stem":"电脑：计算机","options":[{"label":"A","content":"公斤：千克"},{"label":"B","content":"公务员：领导"},{"label":"C","content":"长度：公里"},{"label":"D","content":"专家：学者"}],"answer":"A","explanation":"电脑和计算机指同一事物，公斤和千克是同一计量单位。","no":197},{"id":"1718789647728","type":"single","material":"","stem":"土豆对于（   ）相当于（   ）对于能量","options":[{"label":"A","content":"薯片矿产"},{"label":"B","content":"玉米太阳"},{"label":"C","content":"粮食太阳能"},{"label":"D","content":"根茎淀粉"}],"answer":"C","explanation":"土豆是一种粮食，太阳能是一种能量。","no":198},{"id":"1718789647729","type":"single","material":"","stem":"抱怨：埋怨","options":[{"label":"A","content":"胆怯：怯弱"},{"label":"B","content":"真挚：真实"},{"label":"C","content":"精确：近似"},{"label":"D","content":"隐蔽：避开"}],"answer":"A","explanation":"抱怨与埋怨是近义词，选项中只有A项符合此关系。","no":199},{"id":"1718789647730","type":"single","material":"","stem":"狗：耗子","options":[{"label":"A","content":"虎穴：虎子"},{"label":"B","content":"凤凰：鸡"},{"label":"C","content":"老鼠：粥"},{"label":"D","content":"苍蝇：鸡蛋"}],"answer":"D","explanation":"“狗拿耗子，多管闲事”是俗语，狗拿耗子是主谓关系；“苍蝇不叮无缝的蛋”，苍蝇叮蛋也是主谓关系。","no":200},{"id":"1718789647731","type":"single","material":"","stem":"公交车：乘客：目的地","options":[{"label":"A","content":"测电笔：电工：电器维修"},{"label":"B","content":"米饭：充饥：人类"},{"label":"C","content":"西红柿：菜农：卖菜"},{"label":"D","content":"米饭：桌子：椅子"}],"answer":"A","explanation":"乘客乘坐公交车到达目的地，电工利用测电笔进行电器维修，且公交车和测电笔都是一种工具。故答案为A。","no":201},{"id":"1718789647732","type":"single","material":"","stem":"音符：乐谱：五线谱","options":[{"label":"A","content":"笔画：汉字：金文"},{"label":"B","content":"树木：森林：自然"},{"label":"C","content":"稻穗：稻谷：香米"},{"label":"D","content":"卫星：星云：宇宙"}],"answer":"A","explanation":"音符构成了乐谱，五线谱是乐谱的一种；笔画构成了汉字，金文是汉字的一种。B项，树林组成了森林，森林是自然的一部分，而不是一种；C项，稻穗加工成稻谷，稻谷加工成大米，香米是大米的一种，不能说是稻谷的一种，与题干不同；D项，卫星可以构成星云，星云是宇宙的一部分，而不是一种。故答案选A。","no":202},{"id":"1718789647733","type":"single","material":"","stem":"拍卖公告：拍卖：交付","options":[{"label":"A","content":"起诉：应诉：庭审"},{"label":"B","content":"感冒：服药：发热"},{"label":"C","content":"泡茶：加水：饮用"},{"label":"D","content":"开机：关机：重启"}],"answer":"A","explanation":"先发布拍卖公告，然后拍卖，拍卖成功后再交付；原告先起诉，然后被告应诉，再庭审，均为顺承的步骤。故答案为A。","no":203},{"id":"1718789647734","type":"single","material":"","stem":"航空母舰对于（   ）相当于潜艇对于(   )","options":[{"label":"A","content":"巡洋舰导弹"},{"label":"B","content":"舰载机鱼雷"},{"label":"C","content":"常规动力核动力"},{"label":"D","content":"远程偷袭协同攻击"}],"answer":"B","explanation":"舰载机是航空母舰的主要作战武器，鱼雷是潜艇的主要作战武器。故答案选B。","no":204},{"id":"1718789647735","type":"single","material":"","stem":"鱼饵：鱼竿","options":[{"label":"A","content":"笔：书籍"},{"label":"B","content":"电脑：无线路由器"},{"label":"C","content":"锅铲：炒锅"},{"label":"D","content":"写诗：笔"}],"answer":"C","explanation":"鱼饵和鱼竿为并列关系，钓鱼时二者搭配使用。<br>A项，笔和书籍是并列关系，但二者不需要配套使用，排除。<br>B项，电脑和无线路由器不是并列关系，电脑也不一定需要搭配无线路由器使用，与题干关系不一致，排除。<br>C项，锅铲和炒锅为并列关系，炒菜时二者搭配使用。<br>D项，笔是写诗的工具，二者不是配套关系，排除。<br>故答案选C。","no":205},{"id":"1718789647736","type":"single","material":"","stem":"表扬：赞扬：褒扬","options":[{"label":"A","content":"军事：军队：军人"},{"label":"B","content":"地图：图表：图象"},{"label":"C","content":"特点：特征：特殊"},{"label":"D","content":"计划：谋划：筹划"}],"answer":"D","explanation":"表扬、赞扬、褒扬三者为近义词，词性均为动词；计划、谋划、筹划三者为近义词，且词性均为动词。","no":206},{"id":"1718789647737","type":"single","material":"","stem":"浮光掠影：浅尝辄止","options":[{"label":"A","content":"语重心长：言近旨远"},{"label":"B","content":"声势浩大：气象万千"},{"label":"C","content":"走马观花：蜻蜓点水"},{"label":"D","content":"一夫当关：坚不可摧"}],"answer":"C","explanation":"“浮光掠影”和“浅尝辄止”是近义关系，“走马观花”和“蜻蜓点水”也是近义词，均形容做事不深入。故答案选C。","no":207},{"id":"1718789647738","type":"single","material":"","stem":"问君能有几多愁，恰似一江春水向东流：李煜","options":[{"label":"A","content":"孤帆远影碧空尽，唯见长江天际流：杜牧"},{"label":"B","content":"大庇天下寒士俱欢颜：李白"},{"label":"C","content":"莫等闲，白了少年头，空悲切：岳飞"},{"label":"D","content":"至今思项羽，不肯过江东：秋瑾"}],"answer":"C","explanation":"“问君能有几多愁，恰似一江春水向东流”出自李煜的《虞美人》；“莫等闲，白了少年头，空悲切”出自岳飞的《满江红》。A项“孤帆远影碧空尽，唯见长江天际流”出自李白的《黄鹤楼送孟浩然之广陵》；B项“大庇天下寒士俱欢颜”出自杜甫的《茅屋为秋风所破歌》；D项“至今思项羽，不肯过江东”出自李清照的《夏日绝句》。故答案选C。","no":208},{"id":"1718789647739","type":"single","material":"","stem":"下雨：打雷","options":[{"label":"A","content":"木炭：燃烧"},{"label":"B","content":"读书：小说"},{"label":"C","content":"洪水：溃堤"},{"label":"D","content":"感冒：发烧"}],"answer":"D","explanation":"下雨天可能会打雷；感冒了可能会发烧。故答案选D。","no":209},{"id":"1718789647740","type":"single","material":"","stem":"宗教：基督教：新教","options":[{"label":"A","content":"国家：民族：区域"},{"label":"B","content":"政府：机关：机构"},{"label":"C","content":"心灵：心情：亲情"},{"label":"D","content":"水果：苹果：红富士"}],"answer":"D","explanation":"基督教是一种宗教，新教是基督教的一个教派；苹果是一种水果，红富士是苹果的一个品种。","no":210},{"id":"1718789647741","type":"single","material":"","stem":"七窍生烟：气愤","options":[{"label":"A","content":"同流合污：腐败"},{"label":"B","content":"哀鸿遍野：荒凉"},{"label":"C","content":"琴瑟和鸣：恩爱"},{"label":"D","content":"高雅脱俗：骄傲"}],"answer":"C","explanation":"七窍生烟形容气愤，琴瑟和鸣形容恩爱。A项，同流合污指跟坏人一起干坏事，但未必是腐败；B项，哀鸿遍野比喻在天灾人祸中到处都是流离失所、呻吟呼号的饥民，与荒凉不同；D项，高雅脱俗不是形容骄傲。故答案选C。","no":211},{"id":"1718789647742","type":"single","material":"","stem":"努力对于（   ）相当于学习对于(   )","options":[{"label":"A","content":"创新知识"},{"label":"B","content":"金钱考试"},{"label":"C","content":"前途学历"},{"label":"D","content":"成功学生"}],"answer":"C","explanation":"通过努力获得前途，通过学习获得学历。故答案为C。","no":212},{"id":"1718789647743","type":"single","material":"","stem":"嘉许：赞美：叹为观止","options":[{"label":"A","content":"辩白：辩论：笔墨官司"},{"label":"B","content":"丑化：污蔑：恶语中伤"},{"label":"C","content":"观察：细查：吹毛求疵"},{"label":"D","content":"前进：后退：你追我赶"}],"answer":"B","explanation":"题干三个词为近义关系，感情色彩一致且层层递进，选项中只有B项符合。故答案选B。","no":213},{"id":"1718789647744","type":"single","material":"","stem":"意见：反对","options":[{"label":"A","content":"观点：支持"},{"label":"B","content":"效果：显现"},{"label":"C","content":"建议：解释"},{"label":"D","content":"成功：获得"}],"answer":"A","explanation":"意见有可能会遭到反对，观点有可能会得到支持，且意见和观点是近义关系。故答案为A。","no":214},{"id":"1718789647745","type":"single","material":"","stem":"灯丝：电灯","options":[{"label":"A","content":"桌子：台布"},{"label":"B","content":"讲台：教室"},{"label":"C","content":"玉米：花生"},{"label":"D","content":"麦子：粮食"}],"answer":"B","explanation":"灯丝是电灯的一个组成部分，讲台是教室的一个组成部分。D项，麦子和粮食是种属关系。麦子是粮食的一种。故选择B项。","no":215},{"id":"1718789647746","type":"single","material":"","stem":"富贵花：牡丹","options":[{"label":"A","content":"黄花：菊花"},{"label":"B","content":"月亮：嫦娥"},{"label":"C","content":"芦荟：芦苇"},{"label":"D","content":"荞麦：小麦"}],"answer":"A","explanation":"富贵花是牡丹的别称之一，黄花是菊花的别称之一。故答案选A。","no":216},{"id":"1718789647747","type":"single","material":"","stem":"中旬：上旬：下旬","options":[{"label":"A","content":"孩子：成人：老人"},{"label":"B","content":"上午：中午：下午"},{"label":"C","content":"昨天：今天：明天"},{"label":"D","content":"夏天：春天：秋天"}],"answer":"D","explanation":"中旬在上旬和下旬之间，夏天在春天和秋天之间。故答案选D。","no":217},{"id":"1718789647748","type":"single","material":"","stem":"刻舟：求剑","options":[{"label":"A","content":"买椟：还珠"},{"label":"B","content":"围魏：救赵"},{"label":"C","content":"跋山：涉水"},{"label":"D","content":"循规：蹈矩"}],"answer":"B","explanation":"刻舟是为了求剑，围魏是为了救赵。其他各项都没这种因果关系。","no":218},{"id":"1718789647749","type":"single","material":"","stem":"鞭挞：抨击","options":[{"label":"A","content":"架空：排挤"},{"label":"B","content":"斧正：修改"},{"label":"C","content":"数落：列举"},{"label":"D","content":"水印：胶印"}],"answer":"B","explanation":"鞭挞和抨击都表示指责批评，是近义词；斧正和修改都表示修改，是近义词。A项架空不仅可以指排挤，也可以指凌空或没有根据。","no":219},{"id":"1718789647750","type":"single","material":"","stem":"水：水杯","options":[{"label":"A","content":"地板：房屋"},{"label":"B","content":"货物：集装箱"},{"label":"C","content":"球类：足球"},{"label":"D","content":"道路：汽车"}],"answer":"B","explanation":"水装在水杯里，货物装在集装箱里。","no":220},{"id":"1718789647751","type":"single","material":"","stem":"（   ）对于味同嚼蜡相当于深藏若虚对于(   )","options":[{"label":"A","content":"脍炙人口盛气凌人"},{"label":"B","content":"意味深长锋芒毕露"},{"label":"C","content":"百读不厌狐假虎威"},{"label":"D","content":"丰富多彩大象无形"}],"answer":"B","explanation":"题干中，味同嚼蜡多指说话或文章枯燥无味；深藏若虚比喻人有真才实学，但不爱在人前卖弄。A项脍炙人口比喻好的诗文或事物被众人所称赞；盛气凌人形容傲慢自大，气势逼人。B项意味深长指含蓄深远，耐人寻味；锋芒毕露比喻锐气和才干全都显露出来。C项百读不厌形容诗文或书籍写得非常好，不论读多少遍也不感到厌倦；狐假虎威比喻倚仗别人的势力来欺压人。D项丰富多彩形容内容丰富，花色繁多；大象无形是指最大的形象反而看不见形迹，比喻不要过分的主张，要兼容百态。比较选项与题干，发现B项两词分别与题干构成反义关系；A、C两项中的后半部分均与深藏若虚没有明显逻辑关系；D项的丰富多彩和味同嚼蜡并无关系。故答案选B。","no":221},{"id":"1718789647752","type":"single","material":"","stem":"传递：信息：网络","options":[{"label":"A","content":"搜索：结果：百度"},{"label":"B","content":"运输：货物：卡车"},{"label":"C","content":"编织：毛衣：毛线"},{"label":"D","content":"书写：汉字：毛笔"}],"answer":"B","explanation":"利用网络传递信息，利用卡车运输货物，且传递和运输都是涉及双方活动的词语。A项结果是搜索得出的内容，不符合。","no":222}]};
